import sys
from typing import NoReturn

LEVELS: tuple[str, ...] = ("DEBUG", "INFO", "WARN", "ERROR")


def fail(message: str) -> NoReturn:
    print(f"error: {message}", file=sys.stderr)
    sys.exit(1)


def classify(line: str) -> str | None:
    """Return the level of a well-formed line, or None if it is malformed."""
    for level in LEVELS:
        prefix = level + " "
        if line.startswith(prefix) and len(line) > len(prefix):
            return level
    return None


def main() -> int:
    if len(sys.argv) > 1:
        fail("this program takes no arguments")

    raw: bytes = sys.stdin.buffer.read()
    try:
        text: str = raw.decode("utf-8")
    except UnicodeDecodeError:
        fail("standard input is not valid UTF-8")

    counts: dict[str, int] = {level: 0 for level in LEVELS}
    malformed: int = 0

    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if line == "":
            continue
        level = classify(line)
        if level is None:
            malformed += 1
        else:
            counts[level] += 1

    out: list[str] = []
    for level in LEVELS:
        if counts[level] > 0:
            out.append(f"{level} {counts[level]}")
    if malformed > 0:
        out.append(f"MALFORMED {malformed}")

    for entry in out:
        sys.stdout.write(entry + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

