import os
import re
import sys
from typing import NoReturn

PLACEHOLDER: re.Pattern[str] = re.compile(r"\{\{([A-Za-z0-9_]+)\}\}")
NAME_PATTERN: re.Pattern[str] = re.compile(r"[A-Za-z0-9_]+")


def fail(message: str) -> NoReturn:
    sys.stderr.write(f"error: {message}\n")
    sys.exit(1)


def resolve_inside(arg: str) -> str:
    cwd = os.path.realpath(os.getcwd())
    target = os.path.realpath(arg)
    try:
        inside = os.path.commonpath([cwd, target]) == cwd
    except ValueError:
        inside = False
    if not inside:
        fail(f"path is outside the current directory: {arg!r}")
    return target


def read_text(arg: str) -> str:
    path = resolve_inside(arg)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except OSError:
        fail(f"cannot read file: {arg!r}")
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        fail(f"file is not valid UTF-8: {arg!r}")


def parse_vars(text: str) -> dict[str, str]:
    values: dict[str, str] = {}
    for line in text.split("\n"):
        if line == "":
            continue
        name, sep, value = line.partition("=")
        if sep == "" or NAME_PATTERN.fullmatch(name) is None:
            fail(f"malformed VARS line: {line!r}")
        values[name] = value
    return values


def render(template: str, values: dict[str, str]) -> str:
    out: list[str] = []
    pos = 0
    for match in PLACEHOLDER.finditer(template):
        name = match.group(1)
        if name not in values:
            fail(f"template uses undefined name: {name!r}")
        out.append(template[pos:match.start()])
        out.append(values[name])
        pos = match.end()
    out.append(template[pos:])
    return "".join(out)


def main() -> None:
    args = sys.argv[1:]
    if len(args) != 2:
        fail("usage: PROGRAM TEMPLATE VARS")
    template = read_text(args[0])
    values = parse_vars(read_text(args[1]))
    output = render(template, values)
    if output and not output.endswith("\n"):
        output += "\n"
    sys.stdout.buffer.write(output.encode("utf-8"))
    sys.stdout.flush()


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Replace spaces with underscores in names of regular files directly inside DIR."""

import os
import sys
from pathlib import Path


class Failure(Exception):
    """A condition that makes the program fail."""


def resolve_inside_cwd(raw: str) -> Path:
    cwd = Path.cwd().resolve()
    try:
        target = Path(raw).resolve()
    except (OSError, RuntimeError) as exc:
        raise Failure(f"cannot resolve {raw}: {exc}") from exc
    if not target.is_relative_to(cwd):
        raise Failure(f"{raw} is outside the current working directory")
    return target


def plan_and_apply(folder: Path, do_apply: bool) -> list[str]:
    try:
        with os.scandir(folder) as it:
            names = sorted(
                entry.name
                for entry in it
                if " " in entry.name and entry.is_file(follow_symlinks=False)
            )
    except OSError as exc:
        raise Failure(f"cannot read folder: {exc.strerror}") from exc

    lines: list[str] = []
    done: list[tuple[Path, Path]] = []
    try:
        for old_name in names:
            new_name = old_name.replace(" ", "_")
            old_path = folder / old_name
            new_path = folder / new_name
            if os.path.lexists(new_path):
                lines.append(f"conflict: {old_name}")
                continue
            lines.append(f"{old_name} -> {new_name}")
            if do_apply:
                os.rename(old_path, new_path)
                done.append((old_path, new_path))
    except OSError as exc:
        # Undo the renames made so far, so a failed run leaves files unchanged.
        for src, dst in reversed(done):
            try:
                os.rename(dst, src)
            except OSError:
                pass
        raise Failure(f"rename failed: {exc.strerror}") from exc
    return lines


def main(argv: list[str]) -> list[str]:
    args = argv[1:]
    if len(args) not in (1, 2):
        raise Failure("usage: PROGRAM DIR [--apply]")
    do_apply = False
    if len(args) == 2:
        if args[1] != "--apply":
            raise Failure("second argument must be --apply")
        do_apply = True
    folder = resolve_inside_cwd(args[0])
    if not folder.is_dir():
        raise Failure(f"{args[0]} is not an existing folder")
    return plan_and_apply(folder, do_apply)


def run() -> int:
    try:
        lines = main(sys.argv)
    except Failure as exc:
        sys.stderr.write(f"error: {exc}\n")
        sys.stderr.flush()
        return 1
    output = "".join(line + "\n" for line in lines)
    sys.stdout.buffer.write(output.encode("utf-8"))
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(run())

import os
import sys
from typing import NoReturn


def fail(message: str) -> NoReturn:
    sys.stderr.write(f"error: {message}\n")
    sys.stderr.flush()
    sys.exit(1)


def is_inside(base: str, target: str) -> bool:
    try:
        return os.path.commonpath([base, target]) == base
    except ValueError:
        return False


def resolve_inside(cwd: str, name: str) -> str | None:
    """Return the fully resolved path if NAME is relative and stays inside cwd."""
    if os.path.isabs(name):
        return None
    resolved = os.path.realpath(os.path.join(cwd, name))
    if not is_inside(cwd, resolved):
        return None
    return resolved


def build_output(cwd: str, list_text: str, current: list[str]) -> list[str]:
    out: list[str] = []
    for raw in list_text.split("\n"):
        name = raw[:-1] if raw.endswith("\r") else raw
        if name == "":
            continue
        current[0] = name

        target = resolve_inside(cwd, name)
        if target is None:
            out.append(f"skipped: {name}\n")
            continue

        if not os.path.isfile(target):
            out.append(f"missing: {name}\n")
            continue

        with open(target, "rb") as handle:
            text = handle.read().decode("utf-8")

        out.append(f"== {name} ==\n")
        out.append(text)
        if text != "" and not text.endswith("\n"):
            out.append("\n")
    return out


def main() -> None:
    if len(sys.argv) != 2:
        fail("usage: PROGRAM LIST")

    list_arg = sys.argv[1]
    current: list[str] = [list_arg]

    try:
        cwd = os.path.realpath(os.getcwd())

        list_path = resolve_inside(cwd, list_arg)
        if list_path is None:
            fail(f"list file is outside the working directory: {list_arg}")

        with open(list_path, "rb") as handle:
            list_text = handle.read().decode("utf-8")

        pieces = build_output(cwd, list_text, current)
    except (OSError, ValueError) as exc:
        fail(f"cannot process {current[0]}: {exc}")

    try:
        sys.stdout.buffer.write("".join(pieces).encode("utf-8"))
        sys.stdout.buffer.flush()
    except OSError as exc:
        fail(f"cannot write output: {exc}")


if __name__ == "__main__":
    main()

import os
import stat
import sys
from pathlib import Path


def count_lines(fd: int) -> int:
    lines = 0
    last = b""
    while True:
        chunk = os.read(fd, 65536)
        if not chunk:
            break
        lines += chunk.count(b"\n")
        last = chunk[-1:]
    if last and last != b"\n":
        lines += 1
    return lines


def count_file(arg: str, cwd: Path) -> int | None:
    try:
        resolved = Path(os.path.realpath(arg))
    except (OSError, ValueError):
        return None
    if not resolved.is_relative_to(cwd):
        return None
    try:
        fd = os.open(resolved, os.O_RDONLY | os.O_NONBLOCK)
    except OSError:
        return None
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            return None
        return count_lines(fd)
    except OSError:
        return None
    finally:
        os.close(fd)


def main() -> int:
    args = sys.argv[1:]
    if not args:
        sys.stderr.buffer.write(b"error: no FILE given\n")
        sys.stderr.buffer.flush()
        return 1

    cwd = Path(os.path.realpath(os.getcwd()))
    total = 0
    all_counted = True

    for arg in args:
        name = os.fsencode(arg)
        count = count_file(arg, cwd)
        if count is None:
            sys.stderr.buffer.write(b"error: " + name + b"\n")
            all_counted = False
        else:
            sys.stdout.buffer.write(str(count).encode("ascii") + b" " + name + b"\n")
            total += count

    sys.stdout.buffer.write(b"total " + str(total).encode("ascii") + b"\n")
    sys.stdout.buffer.flush()
    sys.stderr.buffer.flush()
    return 0 if all_counted else 1


if __name__ == "__main__":
    sys.exit(main())

import os
import re
import sys

WHOLE_NUMBER: re.Pattern[str] = re.compile(r"-?[0-9]+")


class Failure(Exception):
    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message: str = message


def inside_cwd(path: str) -> bool:
    cwd: str = os.path.realpath(os.getcwd())
    target: str = os.path.realpath(path)
    try:
        return os.path.commonpath([cwd, target]) == cwd
    except ValueError:
        return False


def read_file(path: str) -> str:
    try:
        with open(path, "rb") as handle:
            data: bytes = handle.read()
    except OSError:
        raise Failure("cannot read file") from None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Failure("file is not valid UTF-8") from None


def sum_column(text: str, column: str) -> int:
    header: list[str] | None = None
    index: int = -1
    total: int = 0
    for number, raw in enumerate(text.split("\n"), start=1):
        if raw.strip() == "":
            continue
        fields: list[str] = [field.strip() for field in raw.split(",")]
        if header is None:
            header = fields
            matches: int = header.count(column)
            if matches == 0:
                raise Failure("column not found in header")
            if matches > 1:
                raise Failure("column name appears more than once in header")
            index = header.index(column)
            continue
        if len(fields) != len(header):
            raise Failure(f"line {number}")
        value: str = fields[index]
        if WHOLE_NUMBER.fullmatch(value) is None:
            raise Failure(f"line {number}")
        total += int(value)
    if header is None:
        raise Failure("no header")
    return total


def run(argv: list[str]) -> int:
    if len(argv) != 2:
        raise Failure("usage: PROGRAM FILE COLUMN")
    file_arg: str = argv[0]
    column: str = argv[1].strip()
    if not inside_cwd(file_arg):
        raise Failure("file is outside the current directory")
    text: str = read_file(os.path.realpath(file_arg))
    return sum_column(text, column)


def main() -> int:
    sys.set_int_max_str_digits(0)
    try:
        total: int = run(sys.argv[1:])
    except Failure as failure:
        sys.stderr.write(f"error: {failure.message}\n")
        return 1
    sys.stdout.write(f"{total}\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())

