import hashlib
import io
import os
import stat
import sys

CHUNK_SIZE: int = 1 << 16


class Failure(Exception):
    """A fatal error that is reported as a single line on standard error."""


def open_regular(path: str) -> io.BufferedReader:
    flags: int = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    fd: int = os.open(path, flags)
    return os.fdopen(fd, "rb")


def file_digest(path: str) -> bytes:
    hasher = hashlib.sha256()
    with open_regular(path) as handle:
        while True:
            chunk: bytes = handle.read(CHUNK_SIZE)
            if not chunk:
                break
            hasher.update(chunk)
    return hasher.digest()


def same_bytes(first: str, second: str) -> bool:
    with open_regular(first) as fa, open_regular(second) as fb:
        while True:
            chunk_a: bytes = fa.read(CHUNK_SIZE)
            chunk_b: bytes = fb.read(CHUNK_SIZE)
            if chunk_a != chunk_b:
                return False
            if not chunk_a:
                return True


def collect(root: str) -> list[tuple[str, str, int]]:
    """Return (full path, relative path, size) for every regular file under root.

    Symbolic links are never followed and never reported.
    """
    found: list[tuple[str, str, int]] = []
    stack: list[tuple[str, str]] = [(root, "")]
    while stack:
        directory, prefix = stack.pop()
        with os.scandir(directory) as entries:
            for entry in entries:
                st = entry.stat(follow_symlinks=False)
                full: str = os.path.join(directory, entry.name)
                rel: str = f"{prefix}/{entry.name}" if prefix else entry.name
                if stat.S_ISDIR(st.st_mode):
                    stack.append((full, rel))
                elif stat.S_ISREG(st.st_mode):
                    found.append((full, rel, st.st_size))
    return found


def find_duplicates(files: list[tuple[str, str, int]]) -> list[list[str]]:
    by_size: dict[int, list[tuple[str, str]]] = {}
    for full, rel, size in files:
        by_size.setdefault(size, []).append((full, rel))

    result: list[list[str]] = []
    for same_size in by_size.values():
        if len(same_size) < 2:
            continue
        by_hash: dict[bytes, list[tuple[str, str]]] = {}
        for full, rel in same_size:
            by_hash.setdefault(file_digest(full), []).append((full, rel))
        for same_hash in by_hash.values():
            if len(same_hash) < 2:
                continue
            classes: list[list[tuple[str, str]]] = []
            for item in same_hash:
                for cls in classes:
                    if same_bytes(cls[0][0], item[0]):
                        cls.append(item)
                        break
                else:
                    classes.append([item])
            for cls in classes:
                if len(cls) >= 2:
                    result.append(sorted(rel for _, rel in cls))
    return result


def run(argv: list[str]) -> bytes:
    if len(argv) != 1:
        raise Failure("usage: PROGRAM DIR")

    base: str = os.path.realpath(os.getcwd())
    target: str = os.path.realpath(argv[0])
    if os.path.commonpath([base, target]) != base:
        raise Failure("DIR is outside the current working directory")
    if not os.path.isdir(target):
        raise Failure("DIR is not an existing folder")

    files = collect(target)
    lines: list[str] = sorted(" ".join(names) for names in find_duplicates(files))
    return b"".join((line + "\n").encode("utf-8") for line in lines)


def main() -> int:
    try:
        payload: bytes = run(sys.argv[1:])
    except (Failure, OSError, UnicodeError, ValueError) as exc:
        message: str = str(exc).replace("\n", " ") or type(exc).__name__
        sys.stderr.write(f"error: {message}\n")
        return 1
    sys.stdout.buffer.write(payload)
    sys.stdout.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())

import re
import sys
from pathlib import Path
from typing import NoReturn

QUANTITY_PATTERN = re.compile(r"[0-9]+")
LINE_BREAK_PATTERN = re.compile(r"\r\n|\r|\n")


def fail(message: str) -> NoReturn:
    print(f"error: {message}", file=sys.stderr)
    sys.exit(1)


def is_inside(path: Path, root: Path) -> bool:
    try:
        return path.resolve().is_relative_to(root)
    except (OSError, RuntimeError):
        return False


def read_file(path: Path, label: str) -> bytes:
    try:
        return path.read_bytes()
    except OSError:
        fail(f"cannot read {label} file")


def decode_text(data: bytes, label: str) -> str:
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        fail(f"{label} file is not valid UTF-8")


def split_lines(text: str) -> list[str]:
    return LINE_BREAK_PATTERN.split(text)


def parse_stock(text: str) -> dict[str, int]:
    stock: dict[str, int] = {}
    for line in split_lines(text):
        parts = line.split()
        if not parts:
            continue
        if len(parts) != 2 or QUANTITY_PATTERN.fullmatch(parts[1]) is None:
            fail("malformed line in STOCK file")
        item, quantity_text = parts
        if item in stock:
            fail("duplicate item in STOCK file")
        stock[item] = int(quantity_text)
    return stock


def main() -> None:
    sys.set_int_max_str_digits(0)

    args = sys.argv[1:]
    if len(args) != 2:
        fail("usage: PROGRAM STOCK ORDERS")

    root = Path.cwd().resolve()
    stock_path = Path(args[0])
    orders_path = Path(args[1])

    if not is_inside(stock_path, root) or not is_inside(orders_path, root):
        fail("path is outside the current directory")

    stock_bytes = read_file(stock_path, "STOCK")
    stock = parse_stock(decode_text(stock_bytes, "STOCK"))

    orders_text = decode_text(read_file(orders_path, "ORDERS"), "ORDERS")

    applied = 0
    for line_number, line in enumerate(split_lines(orders_text), start=1):
        parts = line.split()
        if not parts:
            continue
        if len(parts) != 2 or QUANTITY_PATTERN.fullmatch(parts[1]) is None:
            fail(f"line {line_number}")
        item, quantity_text = parts
        amount = int(quantity_text)
        if amount < 1:
            fail(f"line {line_number}")
        if item not in stock:
            fail(f"line {line_number}")
        if amount > stock[item]:
            fail(f"line {line_number}")
        stock[item] -= amount
        applied += 1

    output = "".join(
        f"{item} {quantity}\n" for item, quantity in sorted(stock.items())
    ).encode("utf-8")

    try:
        stock_path.write_bytes(output)
    except OSError:
        try:
            stock_path.write_bytes(stock_bytes)
        except OSError:
            pass
        fail("cannot write STOCK file")

    print(f"ok {applied}")
    sys.exit(0)


if __name__ == "__main__":
    main()

