def load(path: str, label: str, settings: dict[str, str]) -> None:
    try:
        with open(path, "r", encoding="utf-8") as handle:
            content = handle.read()
    except (OSError, UnicodeDecodeError) as exc:
        raise Failure(f"cannot read {label!r}") from exc

    for number, line in enumerate(content.split("\n"), start=1):
        if line.strip() == "" or line.startswith("#"):
            continue
        if "=" not in line:
            raise Failure(f"malformed line {number} in {label!r}")
        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip()
        if key == "":
            raise Failure(f"empty key on line {number} in {label!r}")
        settings[key] = value


def target_mode(target: str) -> int:
    try:
        return stat.S_IMODE(os.stat(target).st_mode)
    except FileNotFoundError:
        mask = os.umask(0)
        os.umask(mask)
        return 0o666 & ~mask


def write_atomic(target: str, text: str) -> None:
    directory = os.path.dirname(target)
    mode = target_mode(target)
    fd, temp = tempfile.mkstemp(dir=directory, prefix=".settings-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8", newline="\n") as handle:
            handle.write(text)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp, mode)
        os.replace(temp, target)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(temp)
        raise


def main(argv: list[str]) -> int:
    if len(argv) != 3:
        raise Failure("expected exactly three arguments: A B OUT")

    cwd = os.path.realpath(os.getcwd())
    path_a = resolve_inside(argv[0], cwd)
    path_b = resolve_inside(argv[1], cwd)
    path_out = resolve_inside(argv[2], cwd)

    settings: dict[str, str] = {}
    load(path_a, argv[0], settings)
    load(path_b, argv[1], settings)

    text = "".join(f"{key}={settings[key]}\n" for key in sorted(settings))

    try:
        write_atomic(path_out, text)
    except OSError as exc:
        raise Failure(f"cannot write {argv[2]!r}") from exc

    return 0


if __name__ == "__main__":
    try:
        exit_code = main(sys.argv[1:])
    except (Failure, OSError) as error:
        print(f"error: {error}", file=sys.stderr)
        sys.exit(1)
    sys.exit(exit_code)

import * as fs from "node:fs";
import * as path from "node:path";

function fail(message: string): never {
  fs.writeSync(2, `error: ${message}\n`);
  process.exit(1);
}

// Returns the real path of the file if it lies inside the real current
// working directory; otherwise fails.
function resolveInsideCwd(fileArg: string): string {
  let cwdReal: string;
  let fileReal: string;
  try {
    cwdReal = fs.realpathSync(process.cwd());
    fileReal = fs.realpathSync(path.resolve(fileArg));
  } catch {
    return fail(`cannot read file ${fileArg}`);
  }
  const rel = path.relative(cwdReal, fileReal);
  if (
    rel === "" ||
    rel === ".." ||
    rel.startsWith(".." + path.sep) ||
    path.isAbsolute(rel)
  ) {
    return fail(`path is outside the current directory: ${fileArg}`);
  }
  return fileReal;
}

function readText(realPath: string, fileArg: string): string {
  try {
    return fs.readFileSync(realPath, "utf8");
  } catch {
    return fail(`cannot read file ${fileArg}`);
  }
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 2) {
    fail("usage: PROGRAM FILE N");
  }
  const fileArg = args[0] ?? "";
  const nArg = args[1] ?? "";

  if (!/^[0-9]+$/.test(nArg)) {
    fail("N must be a whole number written in digits");
  }
  const n = Number(nArg);
  if (!Number.isSafeInteger(n) || n < 1) {
    fail("N must be at least 1");
  }

  const realPath = resolveInsideCwd(fileArg);
  const text = readText(realPath, fileArg);

  const counts = new Map<string, number>();
  for (const m of text.matchAll(/[A-Za-z]+/g)) {
    const word = (m[0] ?? "").toLowerCase();
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }

  const entries = [...counts.entries()].sort((a, b) => {
    if (b[1] !== a[1]) {
      return b[1] - a[1];
    }
    if (a[0] < b[0]) {
      return -1;
    }
    if (a[0] > b[0]) {
      return 1;
    }
    return 0;
  });

  const out = entries
    .slice(0, n)
    .map(([word, count]) => `${word} ${count}\n`)
    .join("");
  process.stdout.write(out);
}

