import codecs
import os
import stat
import sys
from pathlib import Path


def count_lines(fd: int) -> int:
    lines = 0
    last = b""
    while True:
        chunk = os.read(fd, 65536)
        if not chunk:
            break
        lines += chunk.count(b"\n")
        last = chunk[-1:]
    if last and last != b"\n":
        lines += 1
    return lines


def count_words(fd: int) -> int:
    decoder = codecs.getincrementaldecoder("utf-8")()
    words = 0
    prev_nonspace = False
    while True:
        chunk = os.read(fd, 65536)
        final = not chunk
        text = decoder.decode(chunk, final)
        if text:
            tokens = text.split()
            # A word may continue from the previous chunk; don't count its first piece twice.
            if prev_nonspace and tokens and not text[0].isspace():
                tokens = tokens[1:]
            words += len(tokens)
            prev_nonspace = not text[-1].isspace()
        if final:
            break
    return words


def count_file(arg: str, cwd: Path, words: bool) -> int | None:
    try:
        resolved = Path(os.path.realpath(arg))
    except (OSError, ValueError):
        return None
    if not resolved.is_relative_to(cwd):
        return None
    try:
        fd = os.open(resolved, os.O_RDONLY | os.O_NONBLOCK)
    except OSError:
        return None
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            return None
        if words:
            return count_words(fd)
        return count_lines(fd)
    except (OSError, UnicodeDecodeError):
        return None
    finally:
        os.close(fd)


def main() -> int:
    args = sys.argv[1:]
    words = False
    if args and args[0] == "--words":
        words = True
        args = args[1:]

    if not args:
        sys.stderr.buffer.write(b"error: no FILE given\n")
        sys.stderr.buffer.flush()
        return 1

    cwd = Path(os.path.realpath(os.getcwd()))
    total = 0
    all_counted = True

    for arg in args:
        name = os.fsencode(arg)
        count = count_file(arg, cwd, words)
        if count is None:
            sys.stderr.buffer.write(b"error: " + name + b"\n")
            all_counted = False
        else:
            sys.stdout.buffer.write(str(count).encode("ascii") + b" " + name + b"\n")
            total += count

    sys.stdout.buffer.write(b"total " + str(total).encode("ascii") + b"\n")
    sys.stdout.buffer.flush()
    sys.stderr.buffer.flush()
    return 0 if all_counted else 1


if __name__ == "__main__":
    sys.exit(main())

import re
import sys
from pathlib import Path
from typing import NoReturn

STOCK_QUANTITY_PATTERN = re.compile(r"[0-9]+")
ORDER_QUANTITY_PATTERN = re.compile(r"-?[0-9]+")
LINE_BREAK_PATTERN = re.compile(r"\r\n|\r|\n")


def fail(message: str) -> NoReturn:
    print(f"error: {message}", file=sys.stderr)
    sys.exit(1)


def is_inside(path: Path, root: Path) -> bool:
    try:
        return path.resolve().is_relative_to(root)
    except (OSError, RuntimeError):
        return False


def read_file(path: Path, label: str) -> bytes:
    try:
        return path.read_bytes()
    except OSError:
        fail(f"cannot read {label} file")


def decode_text(data: bytes, label: str) -> str:
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        fail(f"{label} file is not valid UTF-8")


def split_lines(text: str) -> list[str]:
    return LINE_BREAK_PATTERN.split(text)


def parse_stock(text: str) -> dict[str, int]:
    stock: dict[str, int] = {}
    for line in split_lines(text):
        parts = line.split()
        if not parts:
            continue
        if len(parts) != 2 or STOCK_QUANTITY_PATTERN.fullmatch(parts[1]) is None:
            fail("malformed line in STOCK file")
        item, quantity_text = parts
        if item in stock:
            fail("duplicate item in STOCK file")
        stock[item] = int(quantity_text)
    return stock


def main() -> None:
    sys.set_int_max_str_digits(0)

    args = sys.argv[1:]
    if len(args) != 2:
        fail("usage: PROGRAM STOCK ORDERS")

    root = Path.cwd().resolve()
    stock_path = Path(args[0])
    orders_path = Path(args[1])

    if not is_inside(stock_path, root) or not is_inside(orders_path, root):
        fail("path is outside the current directory")

    stock_bytes = read_file(stock_path, "STOCK")
    stock = parse_stock(decode_text(stock_bytes, "STOCK"))

    orders_text = decode_text(read_file(orders_path, "ORDERS"), "ORDERS")

    applied = 0
    for line_number, line in enumerate(split_lines(orders_text), start=1):
        parts = line.split()
        if not parts:
            continue
        if len(parts) != 2 or ORDER_QUANTITY_PATTERN.fullmatch(parts[1]) is None:
            fail(f"line {line_number}")
        item, quantity_text = parts
        amount = int(quantity_text)
        if amount == 0:
            fail(f"line {line_number}")
        if item not in stock:
            fail(f"line {line_number}")
        if amount > stock[item]:
            fail(f"line {line_number}")
        stock[item] -= amount
        applied += 1

    output = "".join(
        f"{item} {quantity}\n" for item, quantity in sorted(stock.items())
    ).encode("utf-8")

    try:
        stock_path.write_bytes(output)
    except OSError:
        try:
            stock_path.write_bytes(stock_bytes)
        except OSError:
            pass
        fail("cannot write STOCK file")

    print(f"ok {applied}")
    sys.exit(0)


if __name__ == "__main__":
    main()

import os
import re
import sys

WHOLE_NUMBER: re.Pattern[str] = re.compile(r"-?[0-9]+")


class Failure(Exception):
    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message: str = message


def inside_cwd(path: str) -> bool:
    cwd: str = os.path.realpath(os.getcwd())
    target: str = os.path.realpath(path)
    try:
        return os.path.commonpath([cwd, target]) == cwd
    except ValueError:
        return False


def read_file(path: str) -> str:
    try:
        with open(path, "rb") as handle:
            data: bytes = handle.read()
    except OSError:
        raise Failure("cannot read file") from None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Failure("file is not valid UTF-8") from None


def parse_columns(spec: str) -> list[str]:
    names: list[str] = [part.strip() for part in spec.split(",")]
    if len(set(names)) != len(names):
        raise Failure("column name is repeated in request")
    return names


def sum_columns(text: str, columns: list[str]) -> list[int]:
    header: list[str] | None = None
    indexes: list[int] = []
    totals: list[int] = [0] * len(columns)
    for number, raw in enumerate(text.split("\n"), start=1):
        if raw.strip() == "":
            continue
        fields: list[str] = [field.strip() for field in raw.split(",")]
        if header is None:
            header = fields
            for column in columns:
                matches: int = header.count(column)
                if matches == 0:
                    raise Failure("column not found in header")
                if matches > 1:
                    raise Failure("column name appears more than once in header")
                indexes.append(header.index(column))
            continue
        if len(fields) != len(header):
            raise Failure(f"line {number}")
        for position, index in enumerate(indexes):
            value: str = fields[index]
            if WHOLE_NUMBER.fullmatch(value) is None:
                raise Failure(f"line {number}")
            totals[position] += int(value)
    if header is None:
        raise Failure("no header")
    return totals


def run(argv: list[str]) -> str:
    if len(argv) != 2:
        raise Failure("usage: PROGRAM FILE COLUMNS")
    file_arg: str = argv[0]
    columns: list[str] = parse_columns(argv[1])
    if not inside_cwd(file_arg):
        raise Failure("file is outside the current directory")
    text: str = read_file(os.path.realpath(file_arg))
    totals: list[int] = sum_columns(text, columns)
    if len(columns) == 1:
        return f"{totals[0]}\n"
    return "".join(
        f"{name}={total}\n" for name, total in zip(columns, totals)
    )


def main() -> int:
    sys.set_int_max_str_digits(0)
    try:
        output: str = run(sys.argv[1:])
    except Failure as failure:
        sys.stderr.write(f"error: {failure.message}\n")
        return 1
    sys.stdout.write(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())

import os
import stat
import sys
import tempfile
from typing import NoReturn


def fail(message: str) -> NoReturn:
    sys.stderr.write(f"error: {message}\n")
    sys.exit(1)


def is_inside(path: str, base: str) -> bool:
    try:
        return os.path.commonpath([base, path]) == base
    except ValueError:
        return False


def resolve_inside(arg: str, base: str) -> str:
    real = os.path.realpath(arg)
    if real == base or not is_inside(real, base):
        fail(f"path is outside the working directory: {arg}")
    return real


def read_lines(path: str) -> list[str]:
    try:
        with open(path, "rb") as f:
            raw = f.read()
    except OSError as exc:
        fail(f"cannot read {path}: {exc.strerror or exc}")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        fail(f"cannot read {path}: not valid UTF-8")
    if text == "":
        return []
    lines = text.split("\n")
    if text.endswith("\n"):
        lines.pop()
    return lines


def dedupe(lines: list[str]) -> list[str]:
    seen: set[str] = set()
    kept: list[str] = []
    for line in lines:
        if line not in seen:
            seen.add(line)
            kept.append(line)
    return kept


def write_atomic(target: str, data: bytes) -> None:
    if os.path.isdir(target):
        fail(f"cannot write {target}: is a directory")
    directory = os.path.dirname(target)
    if not os.path.isdir(directory) or not os.access(directory, os.W_OK | os.X_OK):
        fail(f"cannot write {target}: directory is not writable")

    mode = 0o644
    if os.path.exists(target):
        if not os.access(target, os.W_OK):
            fail(f"cannot write {target}: permission denied")
        mode = stat.S_IMODE(os.stat(target).st_mode)

    try:
        fd, tmp = tempfile.mkstemp(dir=directory, prefix=".dedupe-", suffix=".tmp")
    except OSError as exc:
        fail(f"cannot write {target}: {exc.strerror or exc}")

    try:
        with os.fdopen(fd, "wb") as f:
            f.write(data)
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, target)
    except OSError as exc:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        fail(f"cannot write {target}: {exc.strerror or exc}")


def main() -> int:
    args = sys.argv[1:]
    if len(args) != 2:
        fail("usage: PROGRAM IN OUT")

    base = os.path.realpath(os.getcwd())
    in_path = resolve_inside(args[0], base)
    out_path = resolve_inside(args[1], base)

    if not os.path.isfile(in_path):
        fail(f"cannot read {args[0]}: not a regular file")

    lines = read_lines(in_path)
    kept = dedupe(lines)
    dropped = len(lines) - len(kept)

    data = "".join(line + "\n" for line in kept).encode("utf-8")
    write_atomic(out_path, data)

    sys.stdout.write(f"kept {len(kept)} dropped {dropped}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import * as fs from "node:fs";
import * as path from "node:path";

class Failure extends Error {}

function fail(message: string): never {
  throw new Failure(message);
}

function realOrFail(p: string): string {
  try {
    return fs.realpathSync(p);
  } catch {
    return fail(`cannot read '${p}'`);
  }
}

function readOrFail(p: string): string {
  try {
    return fs.readFileSync(p, "utf8");
  } catch {
    return fail(`cannot read '${p}'`);
  }
}

function splitRow(line: string): string[] {
  return line.split(",").map((f) => f.trim());
}

const WHOLE_NUMBER = /^-?[0-9]+$/;

function run(argv: string[]): string {
  if (argv.length !== 2) {
    fail("usage: PROGRAM FILE COLUMN");
  }
  const fileArg = argv[0] ?? "";
  const column = (argv[1] ?? "").trim();

  const cwdReal = realOrFail(process.cwd());
  const fileReal = realOrFail(fileArg);
  const rel = path.relative(cwdReal, fileReal);
  if (
    rel === "" ||
    rel === ".." ||
    rel.startsWith(".." + path.sep) ||
    path.isAbsolute(rel)
  ) {
    fail(`'${fileArg}' is outside the current directory`);
  }

  const text = readOrFail(fileReal);
  const lines = text.split("\n");

  let header: string[] | undefined;
  let columnIndex = -1;
  let sum = 0n;

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i] ?? "";
    if (raw.trim() === "") {
      continue;
    }
    const lineNo = i + 1;

    if (header === undefined) {
      const h = splitRow(raw);
      columnIndex = h.indexOf(column);
      if (columnIndex < 0) {
        fail(`column '${column}' not found in header`);
      }
      header = h;
      continue;
    }

    const fields = splitRow(raw);
    if (fields.length !== header.length) {
      fail(`line ${lineNo}`);
    }
    const value = fields[columnIndex] ?? "";
    if (!WHOLE_NUMBER.test(value)) {
      fail(`line ${lineNo}`);
    }
    sum += BigInt(value);
  }

  if (header === undefined) {
    fail("no header");
  }

  return sum.toString();
}

function main(): void {
  try {
    const out = run(process.argv.slice(2));
    process.stdout.write(out + "\n");
    process.exitCode = 0;
  } catch (err) {
    const msg = err instanceof Failure ? err.message : String(err);
    fs.writeSync(2, `error: ${msg}\n`);
    process.exit(1);
  }
}

main();

import * as fs from "node:fs";
import * as path from "node:path";

function fail(message: string): never {
  fs.writeSync(2, `error: ${message}\n`);
  process.exit(1);
}

// Returns the real path of the file if it lies inside the real current
// working directory; otherwise fails.
function resolveInsideCwd(fileArg: string): string {
  let cwdReal: string;
  let fileReal: string;
  try {
    cwdReal = fs.realpathSync(process.cwd());
    fileReal = fs.realpathSync(path.resolve(fileArg));
  } catch {
    return fail(`cannot read file ${fileArg}`);
  }
  const rel = path.relative(cwdReal, fileReal);
  if (
    rel === "" ||
    rel === ".." ||
    rel.startsWith(".." + path.sep) ||
    path.isAbsolute(rel)
  ) {
    return fail(`path is outside the current directory: ${fileArg}`);
  }
  return fileReal;
}

function readText(realPath: string, fileArg: string): string {
  try {
    return fs.readFileSync(realPath, "utf8");
  } catch {
    return fail(`cannot read file ${fileArg}`);
  }
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length < 2 || args.length > 3) {
    fail("usage: PROGRAM FILE N [--min-length=K]");
  }
  const fileArg = args[0] ?? "";
  const nArg = args[1] ?? "";

  if (!/^[0-9]+$/.test(nArg)) {
    fail("N must be a whole number written in digits");
  }
  const n = Number(nArg);
  if (!Number.isSafeInteger(n) || n < 1) {
    fail("N must be at least 1");
  }

  let minLength = 1;
  if (args.length === 3) {
    const optArg = args[2] ?? "";
    const opt = /^--min-length=([0-9]+)$/.exec(optArg);
    if (opt === null) {
      fail("third argument must be --min-length=K with K written in digits");
    }
    const k = Number(opt[1] ?? "");
    if (!Number.isSafeInteger(k) || k < 1) {
      fail("K must be at least 1");
    }
    minLength = k;
  }

  const realPath = resolveInsideCwd(fileArg);
  const text = readText(realPath, fileArg);

  const counts = new Map<string, number>();
  for (const m of text.matchAll(/[A-Za-z]+/g)) {
    const raw = m[0] ?? "";
    if (raw.length < minLength) {
      continue;
    }
    const word = raw.toLowerCase();
    counts.set(word, (counts.get(word) ?? 0) + 1);
  }

  const entries = [...counts.entries()].sort((a, b) => {
    if (b[1] !== a[1]) {
      return b[1] - a[1];
    }
    if (a[0] < b[0]) {
      return -1;
    }
    if (a[0] > b[0]) {
      return 1;
    }
    return 0;
  });

  const out = entries
    .slice(0, n)
    .map(([word, count]) => `${word} ${count}\n`)
    .join("");
  process.stdout.write(out);
}

main();

import process from "node:process";

const LEVELS = ["DEBUG", "INFO", "WARN", "ERROR"] as const;
type Level = (typeof LEVELS)[number];

function fail(message: string): number {
  process.stderr.write(`error: ${message}\n`);
  return 1;
}

async function readAllStdin(): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) {
    chunks.push(typeof chunk === "string" ? Buffer.from(chunk, "utf8") : chunk);
  }
  return Buffer.concat(chunks);
}

function levelOf(line: string): Level | undefined {
  for (const level of LEVELS) {
    if (line.startsWith(level + " ") && line.length > level.length + 1) {
      return level;
    }
  }
  return undefined;
}

async function main(): Promise<number> {
  const args = process.argv.slice(2);
  if (args.length > 0) {
    return fail("this program takes no arguments");
  }

  let text: string;
  try {
    text = (await readAllStdin()).toString("utf8");
  } catch {
    return fail("cannot read standard input");
  }

  const counts: Record<Level, number> = {
    DEBUG: 0,
    INFO: 0,
    WARN: 0,
    ERROR: 0,
  };
  let malformed = 0;

  for (const line of text.split("\n")) {
    if (line === "") {
      continue;
    }
    const level = levelOf(line);
    if (level === undefined) {
      malformed++;
    } else {
      counts[level]++;
    }
  }

  let out = "";
  for (const level of LEVELS) {
    if (counts[level] > 0) {
      out += `${level} ${counts[level]}\n`;
    }
  }
  if (malformed > 0) {
    out += `MALFORMED ${malformed}\n`;
  }

  process.stdout.write(out);
  return 0;
}

main().then(
  (code) => {
    process.exitCode = code;
  },
  () => {
    process.stderr.write("error: unexpected failure\n");
    process.exitCode = 1;
  },
);

#!/usr/bin/env python3
"""Keep up to three numbered backups of FILE: FILE.1 (newest), FILE.2, FILE.3."""

import os
import secrets
import shutil
import stat
import sys
from typing import Callable, NoReturn

CWD: str = os.path.realpath(os.getcwd())


def fail(message: str) -> NoReturn:
    print(f"error: {message}", file=sys.stderr)
    sys.exit(1)


def inside_cwd(path: str) -> bool:
    real = os.path.realpath(path)
    try:
        return os.path.commonpath([real, CWD]) == CWD
    except ValueError:
        return False


def make_trash(path: str) -> str:
    directory, name = os.path.split(path)
    while True:
        candidate = os.path.join(directory, f".{name}.rotate-{secrets.token_hex(8)}")
        if not os.path.lexists(candidate):
            return candidate


def copy_new(src: str, dst: str, mode: int) -> None:
    """Copy src to a newly created dst; dst must not already exist."""
    with open(src, "rb") as source:
        fd = os.open(dst, os.O_WRONLY | os.O_CREAT | os.O_EXCL, mode)
        try:
            with os.fdopen(fd, "wb") as target:
                shutil.copyfileobj(source, target)
        except BaseException:
            os.unlink(dst)
            raise


def rotate(path: str, mode: int) -> None:
    b1 = f"{path}.1"
    b2 = f"{path}.2"
    b3 = f"{path}.3"
    undo: list[Callable[[], None]] = []
    trash: str | None = None

    def move(src: str, dst: str) -> None:
        os.rename(src, dst)
        undo.append(lambda: os.rename(dst, src))

    try:
        # 1. Delete FILE.3 (moved aside first so it can be restored on failure).
        if os.path.lexists(b3):
            trash = make_trash(path)
            move(b3, trash)
        # 2. Rename FILE.2 to FILE.3.
        if os.path.lexists(b2):
            move(b2, b3)
        # 3. Rename FILE.1 to FILE.2.
        if os.path.lexists(b1):
            move(b1, b2)
        # 4. Copy FILE to FILE.1, leaving FILE unchanged.
        copy_new(path, b1, mode)
        undo.append(lambda: os.unlink(b1))
        # Commit: discard the displaced old FILE.3.
        if trash is not None:
            os.unlink(trash)
    except OSError as exc:
        for step in reversed(undo):
            try:
                step()
            except OSError:
                pass
        reason = exc.strerror if exc.strerror else str(exc)
        fail(f"rotation failed: {reason}")


def main() -> None:
    if len(sys.argv) != 2:
        fail("usage: PROGRAM FILE")

    path = sys.argv[1]

    for candidate in (path, f"{path}.1", f"{path}.2", f"{path}.3"):
        if not inside_cwd(candidate):
            fail(f"{candidate}: resolves outside the current working directory")

    try:
        info = os.lstat(path)
    except OSError:
        fail(f"{path}: not an existing regular file")

    if not stat.S_ISREG(info.st_mode):
        fail(f"{path}: not an existing regular file")

    rotate(path, stat.S_IMODE(info.st_mode))
    print("rotated")


if __name__ == "__main__":
    main()

import * as fs from "node:fs";
import * as path from "node:path";

function fail(msg: string): never {
  fs.writeSync(2, `error: ${msg}\n`);
  process.exit(1);
}

const cwd: string = fs.realpathSync(process.cwd());

// Resolve a path physically: `..` and symlinks are applied in order, and
// components that do not exist yet are appended as-is.
function physical(start: string, p: string, depth = 0): string {
  if (depth > 40) {
    throw new Error("too many levels of symbolic links");
  }
  let cur = path.isAbsolute(p) ? "/" : start;
  for (const part of p.split("/")) {
    if (part === "" || part === ".") continue;
    if (part === "..") {
      cur = path.dirname(cur);
      continue;
    }
    const next = path.join(cur, part);
    let st: fs.Stats | undefined;
    try {
      st = fs.lstatSync(next);
    } catch {
      st = undefined;
    }
    if (st !== undefined && st.isSymbolicLink()) {
      cur = physical(cur, fs.readlinkSync(next), depth + 1);
    } else {
      cur = next;
    }
  }
  return cur;
}

function isInside(p: string): boolean {
  const rel = path.relative(cwd, p);
  if (rel === "") return true;
  if (path.isAbsolute(rel)) return false;
  if (rel === ".." || rel.startsWith(".." + path.sep)) return false;
  return true;
}

function resolveArg(arg: string): string {
  const resolved = physical(cwd, arg);
  if (!isInside(resolved)) {
    fail(`path is outside the working directory: ${arg}`);
  }
  return resolved;
}

// Compare strings by Unicode code point values.
function compareCodePoints(a: string, b: string): number {
  const x = Array.from(a, (c) => c.codePointAt(0) ?? 0);
  const y = Array.from(b, (c) => c.codePointAt(0) ?? 0);
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const d = (x[i] as number) - (y[i] as number);
    if (d !== 0) return d;
  }
  return x.length - y.length;
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 3) {
    fail("usage: PROGRAM A B OUT");
  }
  const [aArg, bArg, outArg] = args as [string, string, string];

  const aPath = resolveArg(aArg);
  const bPath = resolveArg(bArg);
  const outPath = resolveArg(outArg);

  const entries = new Map<string, string>();

  for (const [label, file] of [
    [aArg, aPath],
    [bArg, bPath],
  ] as const) {
    let text: string;
    try {
      text = fs.readFileSync(file, "utf8");
    } catch {
      fail(`cannot read ${label}`);
    }
    const lines = text.split("\n");
    lines.forEach((raw, idx) => {
      const line = raw.trim();
      if (line === "" || line.startsWith("#")) return;
      const eq = line.indexOf("=");
      if (eq < 0) {
        fail(`malformed line ${idx + 1} in ${label}`);
      }
      const key = line.slice(0, eq).trim();
      if (key === "") {
        fail(`empty key on line ${idx + 1} in ${label}`);
      }
      const value = line.slice(eq + 1).trim();
      entries.set(key, value);
    });
  }

  const keys = [...entries.keys()].sort(compareCodePoints);
  const output = keys.map((k) => `${k}=${entries.get(k) ?? ""}\n`).join("");

  let mode: number | undefined;
  try {
    mode = fs.statSync(outPath).mode & 0o7777;
  } catch {
    mode = undefined;
  }

  const tmp = path.join(
    path.dirname(outPath),
    `.${path.basename(outPath)}.${process.pid}.tmp`,
  );
  try {
    fs.writeFileSync(tmp, output, { flag: "wx", encoding: "utf8" });
    if (mode !== undefined) {
      fs.chmodSync(tmp, mode);
    }
    fs.renameSync(tmp, outPath);
  } catch {
    try {
      fs.rmSync(tmp, { force: true });
    } catch {
      // ignore cleanup failure
    }
    fail(`cannot write ${outArg}`);
  }
}

try {
  main();
} catch (e) {
  const reason = e instanceof Error ? e.message : String(e);
  fail(reason);
}

import * as fs from "node:fs";
import * as path from "node:path";

class Failure extends Error {}

function fail(message: string): never {
  throw new Failure(message);
}

function realOrFail(p: string): string {
  try {
    return fs.realpathSync(p);
  } catch {
    return fail(`cannot read '${p}'`);
  }
}

function readOrFail(p: string): string {
  try {
    return fs.readFileSync(p, "utf8");
  } catch {
    return fail(`cannot read '${p}'`);
  }
}

function splitRow(line: string): string[] {
  return line.split(",").map((f) => f.trim());
}

function splitNames(arg: string): string[] {
  return arg.split(",").map((n) => n.trim());
}

const WHOLE_NUMBER = /^-?[0-9]+$/;

interface Column {
  name: string;
  index: number;
  sum: bigint;
}

function run(argv: string[]): string {
  if (argv.length !== 2) {
    fail("usage: PROGRAM FILE COLUMNS");
  }
  const fileArg = argv[0] ?? "";
  const names = splitNames(argv[1] ?? "");

  const seen = new Set<string>();
  for (const name of names) {
    if (seen.has(name)) {
      fail(`column '${name}' repeated`);
    }
    seen.add(name);
  }

  const cwdReal = realOrFail(process.cwd());
  const fileReal = realOrFail(fileArg);
  const rel = path.relative(cwdReal, fileReal);
  if (
    rel === "" ||
    rel === ".." ||
    rel.startsWith(".." + path.sep) ||
    path.isAbsolute(rel)
  ) {
    fail(`'${fileArg}' is outside the current directory`);
  }

  const text = readOrFail(fileReal);
  const lines = text.split("\n");

  let header: string[] | undefined;
  let cols: Column[] = [];

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i] ?? "";
    if (raw.trim() === "") {
      continue;
    }
    const lineNo = i + 1;

    if (header === undefined) {
      const h = splitRow(raw);
      cols = names.map((name) => {
        const index = h.indexOf(name);
        if (index < 0) {
          fail(`column '${name}' not found in header`);
        }
        return { name, index, sum: 0n };
      });
      header = h;
      continue;
    }

    const fields = splitRow(raw);
    if (fields.length !== header.length) {
      fail(`line ${lineNo}`);
    }
    for (const col of cols) {
      const value = fields[col.index] ?? "";
      if (!WHOLE_NUMBER.test(value)) {
        fail(`line ${lineNo}`);
      }
      col.sum += BigInt(value);
    }
  }

  if (header === undefined) {
    fail("no header");
  }

  const single = cols.length === 1;
  let out = "";
  for (const col of cols) {
    out += single
      ? `${col.sum.toString()}\n`
      : `${col.name}=${col.sum.toString()}\n`;
  }
  return out;
}

function main(): void {
  try {
    const out = run(process.argv.slice(2));
    process.stdout.write(out);
    process.exitCode = 0;
  } catch (err) {
    const msg = err instanceof Failure ? err.message : String(err);
    fs.writeSync(2, `error: ${msg}\n`);
    process.exit(1);
  }
}

main();

import * as fs from "node:fs";
import * as path from "node:path";
import { createHash } from "node:crypto";

interface FileInfo {
  rel: string;
  abs: string;
  size: number;
}

interface Cluster {
  buf: Buffer;
  members: string[];
}

function fail(message: string): never {
  throw new Error(message);
}

function isInside(base: string, target: string): boolean {
  const rel = path.relative(base, target);
  if (rel === "") {
    return true;
  }
  return rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel);
}

function walk(absDir: string, relDir: string, out: FileInfo[]): void {
  const entries = fs.readdirSync(absDir, { withFileTypes: true });
  for (const entry of entries) {
    const abs = path.join(absDir, entry.name);
    const rel = relDir === "" ? entry.name : relDir + "/" + entry.name;
    if (entry.isDirectory()) {
      walk(abs, rel, out);
    } else {
      const st = fs.lstatSync(abs);
      if (st.isFile()) {
        out.push({ rel, abs, size: st.size });
      }
    }
  }
}

function findDuplicateLines(): string[] {
  const args = process.argv.slice(2);
  const arg = args[0];
  if (args.length !== 1 || arg === undefined) {
    fail("expected exactly one argument: DIR");
  }
  if (arg === "") {
    fail("DIR must not be empty");
  }

  const cwdReal = fs.realpathSync(process.cwd());
  let dirReal: string;
  try {
    dirReal = fs.realpathSync(path.resolve(arg));
  } catch {
    fail("DIR does not exist or cannot be resolved");
  }

  if (!isInside(cwdReal, dirReal)) {
    fail("DIR is outside the current working directory");
  }
  if (!fs.statSync(dirReal).isDirectory()) {
    fail("DIR is not a folder");
  }

  const files: FileInfo[] = [];
  walk(dirReal, "", files);

  const bySize = new Map<number, FileInfo[]>();
  for (const f of files) {
    const list = bySize.get(f.size);
    if (list) {
      list.push(f);
    } else {
      bySize.set(f.size, [f]);
    }
  }

  const groups: string[][] = [];
  for (const list of bySize.values()) {
    if (list.length < 2) {
      continue;
    }
    const byHash = new Map<string, Cluster[]>();
    for (const f of list) {
      const buf = fs.readFileSync(f.abs);
      const hash = createHash("sha256").update(buf).digest("hex");
      const bucket = byHash.get(hash) ?? [];
      byHash.set(hash, bucket);
      const hit = bucket.find((c) => c.buf.equals(buf));
      if (hit) {
        hit.members.push(f.rel);
      } else {
        bucket.push({ buf, members: [f.rel] });
      }
    }
    for (const bucket of byHash.values()) {
      for (const cluster of bucket) {
        if (cluster.members.length >= 2) {
          groups.push(cluster.members.slice().sort());
        }
      }
    }
  }

  const lines = groups.map((g) => g.join(" "));
  lines.sort();
  return lines;
}

function main(): void {
  try {
    const lines = findDuplicateLines();
    const text = lines.map((l) => l + "\n").join("");
    process.stdout.write(text);
    process.exitCode = 0;
  } catch (err: unknown) {
    const raw = err instanceof Error ? err.message : String(err);
    const message = raw.replace(/\s*\n\s*/g, " ").trim();
    process.stderr.write("error: " + message + "\n");
    process.exitCode = 1;
  }
}

main();

use std::collections::HashMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn main() {
    let args: Vec<OsString> = env::args_os().collect();
    if args.len() != 3 {
        fail("usage: PROGRAM FILE N");
    }

    // Validate N: digits only, at least 1.
    let n_os = &args[2];
    let n_str = n_os.to_string_lossy();
    if n_str.is_empty() || !n_str.bytes().all(|b| b.is_ascii_digit()) {
        fail("N must be a whole number of at least 1 written in digits");
    }
    let significant = n_str.trim_start_matches('0');
    if significant.is_empty() {
        fail("N must be a whole number of at least 1 written in digits");
    }
    let n: usize = significant.parse().unwrap_or(usize::MAX);

    // Resolve the working directory and the file (following symlinks and "..").
    let cwd = match env::current_dir().and_then(|d| d.canonicalize()) {
        Ok(d) => d,
        Err(_) => fail("cannot determine the current working directory"),
    };

    let file_arg = Path::new(&args[1]);
    let resolved = match file_arg.canonicalize() {
        Ok(p) => p,
        Err(_) => fail("cannot read FILE"),
    };

    if !resolved.starts_with(&cwd) {
        fail("FILE is outside the current working directory");
    }

    let data = match fs::read(&resolved) {
        Ok(d) => d,
        Err(_) => fail("cannot read FILE"),
    };

    // Count words: maximal runs of ASCII letters, lower-cased.
    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    let mut cur: Vec<u8> = Vec::new();
    for &b in data.iter().chain(std::iter::once(&b' ')) {
        if b.is_ascii_alphabetic() {
            cur.push(b.to_ascii_lowercase());
        } else if !cur.is_empty() {
            *counts.entry(std::mem::take(&mut cur)).or_insert(0) += 1;
        }
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let stdout = io::stdout();
    let mut out = stdout.lock();
    for (word, count) in entries.iter().take(n) {
        let w = String::from_utf8_lossy(word);
        let _ = writeln!(out, "{} {}", w, count);
    }
    let _ = out.flush();
    process::exit(0);
}

import * as fs from "node:fs";
import * as path from "node:path";

interface Failure {
  readonly failure: string;
}

function fail(message: string): never {
  const f: Failure = { failure: message };
  throw f;
}

function isFailure(value: unknown): value is Failure {
  return (
    typeof value === "object" &&
    value !== null &&
    "failure" in value &&
    typeof (value as { failure: unknown }).failure === "string"
  );
}

const WHOLE_NUMBER = /^[0-9]+$/;

function realPathOrNull(p: string): string | null {
  try {
    return fs.realpathSync(p);
  } catch {
    return null;
  }
}

function resolveInside(cwdReal: string, arg: string): string {
  const real = realPathOrNull(path.resolve(cwdReal, arg));
  if (real === null) {
    fail(`cannot access ${arg}`);
  }
  const rel = path.relative(cwdReal, real);
  if (
    rel === "" ||
    path.isAbsolute(rel) ||
    rel === ".." ||
    rel.startsWith(".." + path.sep)
  ) {
    fail(`path is outside the working directory: ${arg}`);
  }
  return real;
}

function readText(file: string, label: string): string {
  try {
    return fs.readFileSync(file, "utf8");
  } catch {
    return fail(`cannot read ${label}`);
  }
}

function parseStock(text: string): Map<string, bigint> {
  const stock = new Map<string, bigint>();
  const lines = text.split("\n");
  for (const raw of lines) {
    const line = raw.trim();
    if (line === "") {
      continue;
    }
    const parts = line.split(/\s+/);
    const item = parts[0];
    const qty = parts[1];
    if (parts.length !== 2 || item === undefined || qty === undefined) {
      fail("malformed STOCK line");
    }
    if (!WHOLE_NUMBER.test(qty)) {
      fail("malformed STOCK line");
    }
    if (stock.has(item)) {
      fail(`duplicate item in STOCK: ${item}`);
    }
    stock.set(item, BigInt(qty));
  }
  return stock;
}

function applyOrders(stock: Map<string, bigint>, text: string): number {
  const lines = text.split("\n");
  let applied = 0;
  for (let index = 0; index < lines.length; index++) {
    const lineNo = index + 1;
    const line = (lines[index] ?? "").trim();
    if (line === "") {
      continue;
    }
    const parts = line.split(/\s+/);
    const item = parts[0];
    const qty = parts[1];
    if (
      parts.length !== 2 ||
      item === undefined ||
      qty === undefined ||
      !WHOLE_NUMBER.test(qty)
    ) {
      fail(`line ${lineNo}`);
    }
    const amount = BigInt(qty);
    if (amount < BigInt(1)) {
      fail(`line ${lineNo}`);
    }
    const have = stock.get(item);
    if (have === undefined || amount > have) {
      fail(`line ${lineNo}`);
    }
    stock.set(item, have - amount);
    applied++;
  }
  return applied;
}

function renderStock(stock: Map<string, bigint>): string {
  const items = Array.from(stock.keys());
  items.sort((a, b) => Buffer.compare(Buffer.from(a, "utf8"), Buffer.from(b, "utf8")));
  let out = "";
  for (const item of items) {
    const value = stock.get(item);
    if (value === undefined) {
      fail("internal error");
    }
    out += `${item} ${value.toString()}\n`;
  }
  return out;
}

function writeStock(stockPath: string, content: string): void {
  const tmp = path.join(
    path.dirname(stockPath),
    `.stock-${process.pid}-${Date.now()}.tmp`
  );
  let created = false;
  try {
    fs.writeFileSync(tmp, content, { encoding: "utf8", flag: "wx" });
    created = true;
    fs.renameSync(tmp, stockPath);
  } catch {
    if (created) {
      try {
        fs.rmSync(tmp, { force: true });
      } catch {
        // ignore cleanup failure
      }
    }
    fail("cannot write STOCK");
  }
}

function main(): number {
  const args = process.argv.slice(2);
  if (args.length !== 2) {
    fail("usage: PROGRAM STOCK ORDERS");
  }
  const stockArg = args[0];
  const ordersArg = args[1];
  if (stockArg === undefined || ordersArg === undefined) {
    fail("usage: PROGRAM STOCK ORDERS");
  }

  const cwdReal = fs.realpathSync(process.cwd());
  const stockPath = resolveInside(cwdReal, stockArg);
  const ordersPath = resolveInside(cwdReal, ordersArg);

  const stock = parseStock(readText(stockPath, "STOCK"));
  const ordersText = readText(ordersPath, "ORDERS");

  const applied = applyOrders(stock, ordersText);
  const content = renderStock(stock);

  writeStock(stockPath, content);
  return applied;
}

try {
  const applied = main();
  process.stdout.write(`ok ${applied}\n`);
  process.exitCode = 0;
} catch (err: unknown) {
  const message = isFailure(err) ? err.failure : "unexpected error";
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

import * as fs from "node:fs";
import * as path from "node:path";
import { TextDecoder } from "node:util";

const NAME_PATTERN = /^[A-Za-z0-9_]+$/;
const PLACEHOLDER_PATTERN = /\{\{([A-Za-z0-9_]+)\}\}/g;

function fail(message: string): never {
  throw new Error(message);
}

function resolveInside(baseReal: string, arg: string): string {
  let real: string;
  try {
    real = fs.realpathSync(path.resolve(baseReal, arg));
  } catch {
    return fail("cannot read a file argument");
  }
  const rel = path.relative(baseReal, real);
  if (
    path.isAbsolute(rel) ||
    rel === ".." ||
    rel.startsWith(".." + path.sep)
  ) {
    return fail("a file argument is outside the current directory");
  }
  return real;
}

function readText(baseReal: string, arg: string): string {
  const real = resolveInside(baseReal, arg);
  let bytes: Buffer;
  try {
    bytes = fs.readFileSync(real);
  } catch {
    return fail("cannot read a file argument");
  }
  try {
    return new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes);
  } catch {
    return fail("a file is not valid UTF-8");
  }
}

function parseVars(text: string): Map<string, string> {
  const vars = new Map<string, string>();
  const lines = text.split("\n");
  lines.forEach((line, index) => {
    if (line === "") {
      return;
    }
    const eq = line.indexOf("=");
    if (eq < 0) {
      fail(`malformed VARS line ${index + 1}`);
    }
    const name = line.slice(0, eq);
    if (!NAME_PATTERN.test(name)) {
      fail(`malformed VARS line ${index + 1}`);
    }
    vars.set(name, line.slice(eq + 1));
  });
  return vars;
}

function render(template: string, vars: Map<string, string>): string {
  for (const match of template.matchAll(PLACEHOLDER_PATTERN)) {
    const name = match[1];
    if (name === undefined || !vars.has(name)) {
      fail(`template uses undefined variable ${name ?? ""}`);
    }
  }
  return template.replace(
    PLACEHOLDER_PATTERN,
    (_whole: string, name: string) => vars.get(name) ?? "",
  );
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 2) {
    fail("usage: PROGRAM TEMPLATE VARS");
  }
  const templateArg = args[0];
  const varsArg = args[1];
  if (templateArg === undefined || varsArg === undefined) {
    fail("usage: PROGRAM TEMPLATE VARS");
  }

  const baseReal = fs.realpathSync(process.cwd());
  const template = readText(baseReal, templateArg);
  const varsText = readText(baseReal, varsArg);
  const vars = parseVars(varsText);

  let output = render(template, vars);
  if (output !== "" && !output.endsWith("\n")) {
    output += "\n";
  }
  process.stdout.write(output);
}

try {
  main();
  process.exitCode = 0;
} catch (err) {
  const message =
    err instanceof Error && err.message !== ""
      ? err.message.split("\n")[0] ?? "unexpected failure"
      : "unexpected failure";
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";

class Failure extends Error {}

function fail(message: string): never {
  throw new Failure(message);
}

function isInside(base: string, target: string): boolean {
  const rel = path.relative(base, target);
  return (
    rel !== "" &&
    rel !== ".." &&
    !rel.startsWith(".." + path.sep) &&
    !path.isAbsolute(rel)
  );
}

function resolveInside(cwd: string, arg: string, mustExist: boolean): string {
  const abs = path.resolve(arg);
  let exists = true;
  try {
    fs.lstatSync(abs);
  } catch {
    exists = false;
  }

  let real: string;
  if (exists) {
    real = fs.realpathSync(abs);
  } else {
    if (mustExist) fail(`cannot read ${JSON.stringify(arg)}`);
    real = path.join(fs.realpathSync(path.dirname(abs)), path.basename(abs));
  }

  if (!isInside(cwd, real)) {
    fail(`${JSON.stringify(arg)} is outside the current directory`);
  }
  return real;
}

function readInput(p: string, arg: string): string {
  try {
    return fs.readFileSync(p, "utf8");
  } catch {
    return fail(`cannot read ${JSON.stringify(arg)}`);
  }
}

function writeOutput(p: string, arg: string, content: string): void {
  let mode: number | undefined;
  try {
    if (fs.existsSync(p)) {
      fs.accessSync(p, fs.constants.W_OK);
      mode = fs.statSync(p).mode & 0o777;
    }
  } catch {
    fail(`cannot write ${JSON.stringify(arg)}`);
  }

  const tmp = path.join(
    path.dirname(p),
    `.dedupe-${crypto.randomBytes(8).toString("hex")}.tmp`,
  );
  try {
    fs.writeFileSync(tmp, content, { encoding: "utf8", flag: "wx" });
    if (mode !== undefined) fs.chmodSync(tmp, mode);
    fs.renameSync(tmp, p);
  } catch {
    try {
      fs.rmSync(tmp, { force: true });
    } catch {
      // ignore cleanup failure
    }
    fail(`cannot write ${JSON.stringify(arg)}`);
  }
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 2) fail("usage: PROGRAM IN OUT");
  const inArg = args[0] ?? "";
  const outArg = args[1] ?? "";

  const cwd = fs.realpathSync(process.cwd());
  const inPath = resolveInside(cwd, inArg, true);
  const outPath = resolveInside(cwd, outArg, false);

  const text = readInput(inPath, inArg);
  const lines = text.split("\n");
  if (lines[lines.length - 1] === "") lines.pop();

  const seen = new Set<string>();
  const kept: string[] = [];
  for (const line of lines) {
    if (!seen.has(line)) {
      seen.add(line);
      kept.push(line);
    }
  }

  const body = kept.map((line) => line + "\n").join("");
  writeOutput(outPath, outArg, body);

  process.stdout.write(
    `kept ${kept.length} dropped ${lines.length - kept.length}\n`,
  );
}

try {
  main();
} catch (e) {
  const message = e instanceof Failure ? e.message : "unexpected failure";
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

import * as fs from "node:fs";
import * as path from "node:path";

class Fail extends Error {}

function fail(message: string): never {
  throw new Fail(message);
}

interface Step {
  oldName: string;
  newName: string;
  rename: boolean;
}

function compareCodePoints(a: string, b: string): number {
  const x = Array.from(a);
  const y = Array.from(b);
  const n = Math.min(x.length, y.length);
  for (let i = 0; i < n; i++) {
    const p = x[i]!.codePointAt(0)!;
    const q = y[i]!.codePointAt(0)!;
    if (p !== q) return p - q;
  }
  return x.length - y.length;
}

function isInside(child: string, parent: string): boolean {
  const rel = path.relative(parent, child);
  if (rel === "") return true;
  if (path.isAbsolute(rel)) return false;
  return rel !== ".." && !rel.startsWith(".." + path.sep);
}

function exists(p: string): boolean {
  try {
    fs.lstatSync(p);
    return true;
  } catch {
    return false;
  }
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length < 1 || args.length > 2) {
    fail("usage: PROGRAM DIR [--apply]");
  }
  const dirArg = args[0];
  if (dirArg === undefined || dirArg === "") {
    fail("usage: PROGRAM DIR [--apply]");
  }
  if (args.length === 2 && args[1] !== "--apply") {
    fail("usage: PROGRAM DIR [--apply]");
  }
  const apply = args.length === 2;

  const cwdReal = fs.realpathSync(process.cwd());

  let dirReal: string;
  try {
    dirReal = fs.realpathSync(path.resolve(process.cwd(), dirArg));
  } catch {
    fail("DIR is not an existing folder");
  }

  if (!isInside(dirReal, cwdReal)) {
    fail("DIR is outside the current working directory");
  }
  if (!fs.statSync(dirReal).isDirectory()) {
    fail("DIR is not an existing folder");
  }

  const names = fs.readdirSync(dirReal);
  const taken = new Set<string>(names);

  const candidates = names
    .filter(
      (n) =>
        n.includes(" ") && fs.lstatSync(path.join(dirReal, n)).isFile(),
    )
    .sort(compareCodePoints);

  const steps: Step[] = [];
  for (const oldName of candidates) {
    const newName = oldName.split(" ").join("_");
    if (taken.has(newName)) {
      steps.push({ oldName, newName, rename: false });
      continue;
    }
    taken.delete(oldName);
    taken.add(newName);
    steps.push({ oldName, newName, rename: true });
  }

  if (apply) {
    const done: Step[] = [];
    try {
      for (const s of steps) {
        if (!s.rename) continue;
        const from = path.join(dirReal, s.oldName);
        const to = path.join(dirReal, s.newName);
        if (exists(to)) {
          throw new Error("target appeared");
        }
        fs.renameSync(from, to);
        done.push(s);
      }
    } catch {
      for (const s of done.reverse()) {
        try {
          fs.renameSync(
            path.join(dirReal, s.newName),
            path.join(dirReal, s.oldName),
          );
        } catch {
          // best-effort rollback
        }
      }
      fail("could not rename files; rolled back where possible");
    }
  }

  const lines: string[] = [];
  for (const s of steps) {
    lines.push(
      s.rename
        ? `${s.oldName} -> ${s.newName}`
        : `conflict: ${s.oldName}`,
    );
  }
  process.stdout.write(lines.map((l) => l + "\n").join(""));
}

try {
  main();
} catch (e) {
  const message = e instanceof Fail ? e.message : "unexpected failure";
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

use std::collections::HashMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::Path;
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

// Parses a whole number of at least 1 written in ASCII digits.
fn parse_positive(s: &str) -> Option<usize> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let significant = s.trim_start_matches('0');
    if significant.is_empty() {
        return None;
    }
    Some(significant.parse().unwrap_or(usize::MAX))
}

fn main() {
    let args: Vec<OsString> = env::args_os().collect();
    if args.len() != 3 && args.len() != 4 {
        fail("usage: PROGRAM FILE N [--min-length=K]");
    }

    // Validate N: digits only, at least 1.
    let n_str = args[2].to_string_lossy();
    let n = match parse_positive(&n_str) {
        Some(v) => v,
        None => fail("N must be a whole number of at least 1 written in digits"),
    };

    // Validate the optional --min-length=K argument.
    let min_len: usize = if args.len() == 4 {
        const PREFIX: &str = "--min-length=";
        let opt = args[3].to_string_lossy();
        if !opt.starts_with(PREFIX) {
            fail("the optional third argument must be --min-length=K");
        }
        match parse_positive(&opt[PREFIX.len()..]) {
            Some(k) => k,
            None => fail("K must be a whole number of at least 1 written in digits"),
        }
    } else {
        1
    };

    // Resolve the working directory and the file (following symlinks and "..").
    let cwd = match env::current_dir().and_then(|d| d.canonicalize()) {
        Ok(d) => d,
        Err(_) => fail("cannot determine the current working directory"),
    };

    let file_arg = Path::new(&args[1]);
    let resolved = match file_arg.canonicalize() {
        Ok(p) => p,
        Err(_) => fail("cannot read FILE"),
    };

    if !resolved.starts_with(&cwd) {
        fail("FILE is outside the current working directory");
    }

    let data = match fs::read(&resolved) {
        Ok(d) => d,
        Err(_) => fail("cannot read FILE"),
    };

    // Count words: maximal runs of ASCII letters, lower-cased, at least min_len letters.
    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    let mut cur: Vec<u8> = Vec::new();
    for &b in data.iter().chain(std::iter::once(&b' ')) {
        if b.is_ascii_alphabetic() {
            cur.push(b.to_ascii_lowercase());
        } else if !cur.is_empty() {
            let word = std::mem::take(&mut cur);
            if word.len() >= min_len {
                *counts.entry(word).or_insert(0) += 1;
            }
        }
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let stdout = io::stdout();
    let mut out = stdout.lock();
    for (word, count) in entries.iter().take(n) {
        let w = String::from_utf8_lossy(word);
        let _ = writeln!(out, "{} {}", w, count);
    }
    let _ = out.flush();
    process::exit(0);
}

use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::PathBuf;
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn is_whole_number(s: &str) -> bool {
    let digits = s.strip_prefix('-').unwrap_or(s);
    !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit())
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        fail("usage: PROGRAM FILE COLUMN");
    }

    let file_arg = PathBuf::from(&args[0]);
    let column: String = match args[1].to_str() {
        Some(s) => s.trim().to_owned(),
        None => fail("column name is not valid UTF-8"),
    };

    let cwd = env::current_dir().unwrap_or_else(|_| fail("cannot determine current directory"));
    let cwd = fs::canonicalize(&cwd).unwrap_or_else(|_| fail("cannot determine current directory"));

    let canon = fs::canonicalize(&file_arg).unwrap_or_else(|_| fail("cannot read FILE"));
    if !canon.starts_with(&cwd) {
        fail("FILE is outside the current directory");
    }

    let text = fs::read_to_string(&canon).unwrap_or_else(|_| fail("cannot read FILE"));

    let mut lines = text
        .lines()
        .enumerate()
        .filter(|(_, l)| !l.trim().is_empty());

    let (_, header_line) = lines.next().unwrap_or_else(|| fail("no header"));
    let names: Vec<&str> = header_line.split(',').map(str::trim).collect();

    let mut matches = names
        .iter()
        .enumerate()
        .filter(|(_, n)| **n == column)
        .map(|(i, _)| i);
    let col = match matches.next() {
        None => fail("column not found in header"),
        Some(i) => i,
    };
    if matches.next().is_some() {
        fail("column name is not unique in header");
    }

    let mut total: i64 = 0;
    for (idx, line) in lines {
        let line_no = idx + 1;
        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        if fields.len() != names.len() {
            fail(&format!("line {}", line_no));
        }
        let value = fields[col];
        if !is_whole_number(value) {
            fail(&format!("line {}", line_no));
        }
        let n: i64 = value
            .parse()
            .unwrap_or_else(|_| fail(&format!("line {}", line_no)));
        total = total
            .checked_add(n)
            .unwrap_or_else(|| fail("sum overflows a 64-bit signed integer"));
    }

    println!("{}", total);
}

import * as fs from "node:fs";
import * as path from "node:path";

let cwdReal = "";

function fail(message: string): void {
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

function insideCwd(p: string): boolean {
  if (p === cwdReal) {
    return true;
  }
  const prefix = cwdReal.endsWith(path.sep) ? cwdReal : cwdReal + path.sep;
  return p.startsWith(prefix);
}

function isAncestorOfCwd(p: string): boolean {
  if (p === cwdReal) {
    return false;
  }
  const prefix = p.endsWith(path.sep) ? p : p + path.sep;
  return cwdReal.startsWith(prefix);
}

// Paths we may inspect: inside the working directory, or its ancestors
// (which a process must traverse to reach the working directory anyway).
function allowed(p: string): boolean {
  return insideCwd(p) || isAncestorOfCwd(p);
}

// Resolves a relative or absolute name step by step, following symbolic
// links and ".." physically. Returns the fully resolved path if it lies
// inside the working directory (existing or not), otherwise null.
// It never inspects a location outside the working directory's ancestry.
function resolveWithin(rel: string): string | null {
  let cur = path.isAbsolute(rel) ? path.parse(rel).root : cwdReal;
  const pending = rel.split("/");
  let hops = 0;

  while (pending.length > 0) {
    const c = pending.shift() as string;
    if (c === "" || c === ".") {
      continue;
    }
    if (c === "..") {
      const up = path.dirname(cur);
      if (!allowed(up)) {
        return null;
      }
      cur = up;
      continue;
    }

    const next = path.join(cur, c);
    if (!allowed(next)) {
      return null;
    }

    let st: fs.Stats;
    try {
      st = fs.lstatSync(next);
    } catch (_e) {
      // Does not exist: the remaining components are resolved lexically.
      const joined = path.join(next, ...pending);
      return insideCwd(joined) ? joined : null;
    }

    if (st.isSymbolicLink()) {
      hops += 1;
      if (hops > 40) {
        return null;
      }
      const target = fs.readlinkSync(next);
      if (path.isAbsolute(target)) {
        cur = path.parse(target).root;
      }
      pending.unshift(...target.split("/"));
    } else {
      cur = next;
    }
  }

  return insideCwd(cur) ? cur : null;
}

function main(): void {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    fail("usage: PROGRAM LIST");
    return;
  }
  const listArg = args[0] as string;

  cwdReal = fs.realpathSync(process.cwd());

  const listPath = resolveWithin(listArg);
  if (listPath === null) {
    fail(`LIST is outside the current directory: ${listArg}`);
    return;
  }

  let listText: string;
  try {
    listText = fs.readFileSync(listPath, "utf8");
  } catch (_e) {
    fail(`cannot read LIST: ${listArg}`);
    return;
  }

  let out = "";
  for (const raw of listText.split("\n")) {
    const name = raw.endsWith("\r") ? raw.slice(0, -1) : raw;
    if (name === "") {
      continue;
    }

    if (path.isAbsolute(name)) {
      out += `skipped: ${name}\n`;
      continue;
    }

    const real = resolveWithin(name);
    if (real === null) {
      out += `skipped: ${name}\n`;
      continue;
    }

    let isFile = false;
    try {
      isFile = fs.statSync(real).isFile();
    } catch (_e) {
      isFile = false;
    }
    if (!isFile) {
      out += `missing: ${name}\n`;
      continue;
    }

    let content: string;
    try {
      content = fs.readFileSync(real, "utf8");
    } catch (_e) {
      fail(`cannot read: ${name}`);
      return;
    }

    out += `== ${name} ==\n`;
    out += content;
    if (!content.endsWith("\n")) {
      out += "\n";
    }
  }

  process.stdout.write(out);
}

try {
  main();
} catch (err) {
  const message = err instanceof Error ? err.message : String(err);
  fail(message);
}

import * as fs from "node:fs";
import * as path from "node:path";

interface Failure {
  readonly failure: string;
}

function fail(message: string): never {
  const f: Failure = { failure: message };
  throw f;
}

function isFailure(value: unknown): value is Failure {
  return (
    typeof value === "object" &&
    value !== null &&
    "failure" in value &&
    typeof (value as { failure: unknown }).failure === "string"
  );
}

const WHOLE_NUMBER = /^[0-9]+$/;
const SIGNED_WHOLE_NUMBER = /^-?[0-9]+$/;

function realPathOrNull(p: string): string | null {
  try {
    return fs.realpathSync(p);
  } catch {
    return null;
  }
}

function resolveInside(cwdReal: string, arg: string): string {
  const real = realPathOrNull(path.resolve(cwdReal, arg));
  if (real === null) {
    fail(`cannot access ${arg}`);
  }
  const rel = path.relative(cwdReal, real);
  if (
    rel === "" ||
    path.isAbsolute(rel) ||
    rel === ".." ||
    rel.startsWith(".." + path.sep)
  ) {
    fail(`path is outside the working directory: ${arg}`);
  }
  return real;
}

function readText(file: string, label: string): string {
  try {
    return fs.readFileSync(file, "utf8");
  } catch {
    return fail(`cannot read ${label}`);
  }
}

function parseStock(text: string): Map<string, bigint> {
  const stock = new Map<string, bigint>();
  const lines = text.split("\n");
  for (const raw of lines) {
    const line = raw.trim();
    if (line === "") {
      continue;
    }
    const parts = line.split(/\s+/);
    const item = parts[0];
    const qty = parts[1];
    if (parts.length !== 2 || item === undefined || qty === undefined) {
      fail("malformed STOCK line");
    }
    if (!WHOLE_NUMBER.test(qty)) {
      fail("malformed STOCK line");
    }
    if (stock.has(item)) {
      fail(`duplicate item in STOCK: ${item}`);
    }
    stock.set(item, BigInt(qty));
  }
  return stock;
}

function applyOrders(stock: Map<string, bigint>, text: string): number {
  const lines = text.split("\n");
  let applied = 0;
  for (let index = 0; index < lines.length; index++) {
    const lineNo = index + 1;
    const line = (lines[index] ?? "").trim();
    if (line === "") {
      continue;
    }
    const parts = line.split(/\s+/);
    const item = parts[0];
    const qty = parts[1];
    if (
      parts.length !== 2 ||
      item === undefined ||
      qty === undefined ||
      !SIGNED_WHOLE_NUMBER.test(qty)
    ) {
      fail(`line ${lineNo}`);
    }
    // amount > 0: order (subtract); amount < 0: restock (add); amount == 0 is malformed
    const amount = BigInt(qty);
    if (amount === BigInt(0)) {
      fail(`line ${lineNo}`);
    }
    const have = stock.get(item);
    if (have === undefined) {
      fail(`line ${lineNo}`);
    }
    if (amount > BigInt(0) && amount > have) {
      fail(`line ${lineNo}`);
    }
    stock.set(item, have - amount);
    applied++;
  }
  return applied;
}

function renderStock(stock: Map<string, bigint>): string {
  const items = Array.from(stock.keys());
  items.sort((a, b) => Buffer.compare(Buffer.from(a, "utf8"), Buffer.from(b, "utf8")));
  let out = "";
  for (const item of items) {
    const value = stock.get(item);
    if (value === undefined) {
      fail("internal error");
    }
    out += `${item} ${value.toString()}\n`;
  }
  return out;
}

function writeStock(stockPath: string, content: string): void {
  const tmp = path.join(
    path.dirname(stockPath),
    `.stock-${process.pid}-${Date.now()}.tmp`
  );
  let created = false;
  try {
    fs.writeFileSync(tmp, content, { encoding: "utf8", flag: "wx" });
    created = true;
    fs.renameSync(tmp, stockPath);
  } catch {
    if (created) {
      try {
        fs.rmSync(tmp, { force: true });
      } catch {
        // ignore cleanup failure
      }
    }
    fail("cannot write STOCK");
  }
}

function main(): number {
  const args = process.argv.slice(2);
  if (args.length !== 2) {
    fail("usage: PROGRAM STOCK ORDERS");
  }
  const stockArg = args[0];
  const ordersArg = args[1];
  if (stockArg === undefined || ordersArg === undefined) {
    fail("usage: PROGRAM STOCK ORDERS");
  }

  const cwdReal = fs.realpathSync(process.cwd());
  const stockPath = resolveInside(cwdReal, stockArg);
  const ordersPath = resolveInside(cwdReal, ordersArg);

  const stock = parseStock(readText(stockPath, "STOCK"));
  const ordersText = readText(ordersPath, "ORDERS");

  const applied = applyOrders(stock, ordersText);
  const content = renderStock(stock);

  writeStock(stockPath, content);
  return applied;
}

try {
  const applied = main();
  process.stdout.write(`ok ${applied}\n`);
  process.exitCode = 0;
} catch (err: unknown) {
  const message = isFailure(err) ? err.failure : "unexpected error";
  process.stderr.write(`error: ${message}\n`);
  process.exitCode = 1;
}

use std::collections::BTreeMap;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn resolve(arg: &str, cwd: &Path) -> Result<PathBuf, String> {
    let path = Path::new(arg);
    let resolved = match fs::canonicalize(path) {
        Ok(p) => p,
        Err(e) => {
            // Path exists as a link (possibly dangling) but cannot be resolved: fail.
            if fs::symlink_metadata(path).is_ok() {
                return Err(format!("cannot resolve '{}': {}", arg, e));
            }
            let name = match path.file_name() {
                Some(n) => n,
                None => return Err(format!("invalid path '{}'", arg)),
            };
            let parent = match path.parent() {
                Some(p) if !p.as_os_str().is_empty() => p,
                _ => Path::new("."),
            };
            let canon_parent = fs::canonicalize(parent)
                .map_err(|e| format!("cannot access '{}': {}", arg, e))?;
            canon_parent.join(name)
        }
    };
    if !resolved.starts_with(cwd) {
        return Err(format!("'{}' is outside the working directory", arg));
    }
    Ok(resolved)
}

fn parse_into(text: &str, map: &mut BTreeMap<String, String>) -> Result<(), String> {
    for (idx, line) in text.lines().enumerate() {
        if line.trim().is_empty() || line.starts_with('#') {
            continue;
        }
        let (k, v) = line
            .split_once('=')
            .ok_or_else(|| format!("line {}: missing '='", idx + 1))?;
        let key = k.trim();
        if key.is_empty() {
            return Err(format!("line {}: empty key", idx + 1));
        }
        map.insert(key.to_string(), v.trim().to_string());
    }
    Ok(())
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    if args.len() != 3 {
        fail("usage: PROGRAM A B OUT");
    }

    let cwd = env::current_dir()
        .and_then(|p| fs::canonicalize(p))
        .unwrap_or_else(|e| fail(&format!("cannot determine working directory: {}", e)));

    let a = resolve(&args[0], &cwd).unwrap_or_else(|e| fail(&e));
    let b = resolve(&args[1], &cwd).unwrap_or_else(|e| fail(&e));
    let out = resolve(&args[2], &cwd).unwrap_or_else(|e| fail(&e));

    let mut map: BTreeMap<String, String> = BTreeMap::new();

    for (name, path) in [(&args[0], &a), (&args[1], &b)] {
        let text = fs::read_to_string(path)
            .unwrap_or_else(|e| fail(&format!("cannot read '{}': {}", name, e)));
        parse_into(&text, &mut map).unwrap_or_else(|e| fail(&format!("'{}': {}", name, e)));
    }

    let mut content = String::new();
    for (k, v) in &map {
        content.push_str(k);
        content.push('=');
        content.push_str(v);
        content.push('\n');
    }

    fs::write(&out, content)
        .unwrap_or_else(|e| fail(&format!("cannot write '{}': {}", args[2], e)));
}

import * as fs from "node:fs";
import * as path from "node:path";

class Failure extends Error {}

function fail(message: string): never {
  throw new Failure(message);
}

function errCode(err: unknown): string | undefined {
  if (typeof err === "object" && err !== null && "code" in err) {
    return String((err as { code: unknown }).code);
  }
  return undefined;
}

function lstatOrNull(p: string): fs.Stats | null {
  try {
    return fs.lstatSync(p);
  } catch (err) {
    if (errCode(err) === "ENOENT") return null;
    throw err;
  }
}

// True if child equals parent or lies strictly inside it (both already resolved).
function isInside(child: string, parent: string): boolean {
  const rel = path.relative(parent, child);
  if (rel === "") return true;
  if (path.isAbsolute(rel)) return false;
  return rel !== ".." && !rel.startsWith(".." + path.sep);
}

// Returns a path in dir that does not currently exist.
function freeName(dir: string, stem: string): string {
  for (let i = 0; ; i++) {
    const p = path.join(dir, `${stem}.${process.pid}.${i}`);
    if (lstatOrNull(p) === null) return p;
  }
}

function resolveParentDir(resolved: string, arg: string): string {
  try {
    return fs.realpathSync(path.dirname(resolved));
  } catch {
    return fail(`cannot access the directory of ${arg}`);
  }
}

function rotate(argv: string[]): void {
  const arg = argv.length === 1 ? argv[0] : undefined;
  if (arg === undefined) {
    fail("usage: PROGRAM FILE");
  }

  const cwdReal = fs.realpathSync(process.cwd());
  const resolved = path.resolve(process.cwd(), arg);
  const base = path.basename(resolved);
  const dirReal = resolveParentDir(resolved, arg);

  if (!isInside(dirReal, cwdReal)) {
    fail(`${arg} is outside the current directory`);
  }

  const target = path.join(dirReal, base);
  const st = lstatOrNull(target);
  if (st === null) {
    fail(`${arg} does not exist`);
  }
  if (!st.isFile()) {
    fail(`${arg} is not a regular file`);
  }

  const bak = (n: number): string => path.join(dirReal, `${base}.${n}`);

  // Validate backup names before changing anything.
  for (const n of [1, 2, 3]) {
    const s = lstatOrNull(bak(n));
    if (s !== null && s.isDirectory()) {
      fail(`${base}.${n} is a directory`);
    }
  }

  // Undo actions, run in reverse order if any step fails.
  const undo: Array<() => void> = [];

  try {
    // 1. Delete FILE.3: move it aside first so it can be restored on failure.
    if (lstatOrNull(bak(3)) !== null) {
      const trash = freeName(dirReal, `${base}.rotate-trash`);
      fs.renameSync(bak(3), trash);
      undo.push(() => fs.renameSync(trash, bak(3)));
      undo.push(() => {
        /* placeholder replaced below */
      });
      undo.pop();

      // 5 (deferred). The trash is removed last, after everything else succeeded.
      // Record it so it can be finalized after the copy step.
      pendingTrash = trash;
    }

    // 2. Rename FILE.2 to FILE.3.
    if (lstatOrNull(bak(2)) !== null) {
      fs.renameSync(bak(2), bak(3));
      undo.push(() => fs.renameSync(bak(3), bak(2)));
    }

    // 3. Rename FILE.1 to FILE.2.
    if (lstatOrNull(bak(1)) !== null) {
      fs.renameSync(bak(1), bak(2));
      undo.push(() => fs.renameSync(bak(2), bak(1)));
    }

    // 4. Copy FILE to FILE.1, never overwriting anything.
    try {
      fs.copyFileSync(target, bak(1), fs.constants.COPYFILE_EXCL);
    } catch (err) {
      if (errCode(err) !== "EEXIST" && lstatOrNull(bak(1)) !== null) {
        fs.unlinkSync(bak(1));
      }
      throw err;
    }
    undo.push(() => fs.unlinkSync(bak(1)));

    // Finally remove the set-aside FILE.3.
    if (pendingTrash !== undefined) {
      fs.unlinkSync(pendingTrash);
    }
  } catch (err) {
    for (const u of undo.reverse()) {
      try {
        u();
      } catch {
        // Best effort during rollback.
      }
    }
    throw err;
  }
}

let pendingTrash: string | undefined;

function main(): void {
  try {
    rotate(process.argv.slice(2));
    process.stdout.write("rotated\n");
    process.exitCode = 0;
  } catch (err) {
    let msg: string;
    if (err instanceof Error) {
      msg = err.message;
    } else {
      msg = String(err);
    }
    msg = msg.replace(/\s*\n\s*/g, " ");
    process.stderr.write(`error: ${msg}\n`);
    process.exitCode = 1;
  }
}

main();

use std::io::{self, Read, Write};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn main() {
    if std::env::args_os().count() > 1 {
        fail("this program takes no arguments");
    }

    let mut buf = Vec::new();
    if let Err(e) = io::stdin().lock().read_to_end(&mut buf) {
        fail(&format!("cannot read standard input: {}", e));
    }

    const LEVELS: [&str; 4] = ["DEBUG", "INFO", "WARN", "ERROR"];
    let mut counts = [0usize; 4];
    let mut malformed: usize = 0;

    for raw in buf.split(|&b| b == b'\n') {
        let raw = raw.strip_suffix(&[b'\r']).unwrap_or(raw);
        if raw.is_empty() {
            continue;
        }

        let s = match std::str::from_utf8(raw) {
            Ok(s) => s,
            Err(_) => {
                malformed += 1;
                continue;
            }
        };

        let mut matched = false;
        for (i, lvl) in LEVELS.iter().enumerate() {
            if let Some(rest) = s.strip_prefix(lvl).and_then(|r| r.strip_prefix(' ')) {
                if !rest.is_empty() {
                    counts[i] += 1;
                    matched = true;
                }
                break;
            }
        }
        if !matched {
            malformed += 1;
        }
    }

    let mut out = String::new();
    for (i, lvl) in LEVELS.iter().enumerate() {
        if counts[i] > 0 {
            out.push_str(&format!("{} {}\n", lvl, counts[i]));
        }
    }
    if malformed > 0 {
        out.push_str(&format!("MALFORMED {}\n", malformed));
    }

    let stdout = io::stdout();
    let mut lock = stdout.lock();
    if let Err(e) = lock.write_all(out.as_bytes()).and_then(|_| lock.flush()) {
        fail(&format!("cannot write standard output: {}", e));
    }
    process::exit(0);
}

use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::PathBuf;
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn is_whole_number(s: &str) -> bool {
    let digits = s.strip_prefix('-').unwrap_or(s);
    !digits.is_empty() && digits.bytes().all(|b| b.is_ascii_digit())
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        fail("usage: PROGRAM FILE COLUMNS");
    }

    let file_arg = PathBuf::from(&args[0]);
    let columns_arg: String = match args[1].to_str() {
        Some(s) => s.to_owned(),
        None => fail("column names are not valid UTF-8"),
    };

    let requested: Vec<String> = columns_arg
        .split(',')
        .map(|s| s.trim().to_owned())
        .collect();

    for i in 0..requested.len() {
        for j in (i + 1)..requested.len() {
            if requested[i] == requested[j] {
                fail("column name is repeated in COLUMNS");
            }
        }
    }

    let cwd = env::current_dir().unwrap_or_else(|_| fail("cannot determine current directory"));
    let cwd = fs::canonicalize(&cwd).unwrap_or_else(|_| fail("cannot determine current directory"));

    let canon = fs::canonicalize(&file_arg).unwrap_or_else(|_| fail("cannot read FILE"));
    if !canon.starts_with(&cwd) {
        fail("FILE is outside the current directory");
    }

    let text = fs::read_to_string(&canon).unwrap_or_else(|_| fail("cannot read FILE"));

    let mut lines = text
        .lines()
        .enumerate()
        .filter(|(_, l)| !l.trim().is_empty());

    let (_, header_line) = lines.next().unwrap_or_else(|| fail("no header"));
    let names: Vec<&str> = header_line.split(',').map(str::trim).collect();

    let mut cols: Vec<usize> = Vec::with_capacity(requested.len());
    for req in &requested {
        let mut matches = names
            .iter()
            .enumerate()
            .filter(|(_, n)| **n == req.as_str())
            .map(|(i, _)| i);
        let col = match matches.next() {
            None => fail("column not found in header"),
            Some(i) => i,
        };
        if matches.next().is_some() {
            fail("column name is not unique in header");
        }
        cols.push(col);
    }

    // First pass: validate every row and extract the requested values.
    let mut rows: Vec<Vec<i64>> = Vec::new();
    for (idx, line) in lines {
        let line_no = idx + 1;
        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        if fields.len() != names.len() {
            fail(&format!("line {}", line_no));
        }
        let mut row_values: Vec<i64> = Vec::with_capacity(cols.len());
        for &col in &cols {
            let value = fields[col];
            if !is_whole_number(value) {
                fail(&format!("line {}", line_no));
            }
            let n: i64 = value
                .parse()
                .unwrap_or_else(|_| fail(&format!("line {}", line_no)));
            row_values.push(n);
        }
        rows.push(row_values);
    }

    // Second pass: sum each requested column.
    let mut totals: Vec<i64> = vec![0; cols.len()];
    for row_values in &rows {
        for (k, &n) in row_values.iter().enumerate() {
            totals[k] = totals[k]
                .checked_add(n)
                .unwrap_or_else(|| fail("sum overflows a 64-bit signed integer"));
        }
    }

    if requested.len() == 1 {
        println!("{}", totals[0]);
    } else {
        for (k, name) in requested.iter().enumerate() {
            println!("{}={}", name, totals[k]);
        }
    }
}

use std::collections::BTreeMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn parse_qty(s: &str) -> Option<u64> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse::<u64>().ok()
}

fn resolve(arg: &OsString, cwd: &Path) -> PathBuf {
    let shown = format!("{:?}", arg);
    let p = match fs::canonicalize(arg) {
        Ok(p) => p,
        Err(_) => fail(&format!("cannot read {}", shown)),
    };
    if !p.starts_with(cwd) {
        fail(&format!("path outside working directory: {}", shown));
    }
    p
}

fn read_file(p: &Path) -> String {
    match fs::read_to_string(p) {
        Ok(s) => s,
        Err(_) => fail(&format!("cannot read {:?}", p.display().to_string())),
    }
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        fail("usage: PROGRAM STOCK ORDERS");
    }

    let cwd = match env::current_dir().and_then(fs::canonicalize) {
        Ok(p) => p,
        Err(_) => fail("cannot determine working directory"),
    };

    let stock_path = resolve(&args[0], &cwd);
    let orders_path = resolve(&args[1], &cwd);

    let stock_text = read_file(&stock_path);
    let orders_text = read_file(&orders_path);

    // Parse STOCK.
    let mut stock: BTreeMap<String, u64> = BTreeMap::new();
    for line in stock_text.lines() {
        let toks: Vec<&str> = line.split_whitespace().collect();
        if toks.is_empty() {
            continue;
        }
        if toks.len() != 2 {
            fail("malformed line in STOCK");
        }
        let qty = match parse_qty(toks[1]) {
            Some(q) => q,
            None => fail("malformed line in STOCK"),
        };
        if stock.contains_key(toks[0]) {
            fail("duplicate item in STOCK");
        }
        stock.insert(toks[0].to_string(), qty);
    }

    // Apply ORDERS in memory; nothing is written until all succeed.
    let mut applied: u64 = 0;
    for (i, line) in orders_text.lines().enumerate() {
        let n = i + 1;
        let toks: Vec<&str> = line.split_whitespace().collect();
        if toks.is_empty() {
            continue;
        }
        if toks.len() != 2 {
            fail(&format!("line {}", n));
        }
        let qty = match parse_qty(toks[1]) {
            Some(q) if q >= 1 => q,
            _ => fail(&format!("line {}", n)),
        };
        match stock.get_mut(toks[0]) {
            None => fail(&format!("line {}", n)),
            Some(left) => {
                if qty > *left {
                    fail(&format!("line {}", n));
                }
                *left -= qty;
            }
        }
        applied += 1;
    }

    // Build the new STOCK contents (BTreeMap iterates in byte/code-point order).
    let mut out = String::new();
    for (item, qty) in &stock {
        out.push_str(item);
        out.push(' ');
        out.push_str(&qty.to_string());
        out.push('\n');
    }

    if fs::write(&stock_path, out.as_bytes()).is_err() {
        fail(&format!("cannot write {:?}", stock_path.display().to_string()));
    }

    println!("ok {}", applied);
    process::exit(0);
}

use std::env;
use std::ffi::OsString;
use std::fs::{self, File};
use std::io::{self, Read};
use std::path::Path;
use std::process;

fn count_lines(file: &mut File) -> io::Result<u64> {
    let mut buf = [0u8; 65536];
    let mut count: u64 = 0;
    let mut last: Option<u8> = None;
    loop {
        let n = match file.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        };
        count += buf[..n].iter().filter(|&&b| b == b'\n').count() as u64;
        last = Some(buf[n - 1]);
    }
    if let Some(b) = last {
        if b != b'\n' {
            count += 1;
        }
    }
    Ok(count)
}

fn count_file(cwd: &Path, path: &Path) -> Result<u64, ()> {
    let resolved = fs::canonicalize(path).map_err(|_| ())?;
    if !resolved.starts_with(cwd) {
        return Err(());
    }
    let meta = fs::metadata(&resolved).map_err(|_| ())?;
    if !meta.is_file() {
        return Err(());
    }
    let mut f = File::open(&resolved).map_err(|_| ())?;
    count_lines(&mut f).map_err(|_| ())
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.is_empty() {
        eprintln!("error: no FILE given");
        process::exit(1);
    }

    let cwd = match env::current_dir().and_then(fs::canonicalize) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("error: cannot determine current directory: {}", e);
            process::exit(1);
        }
    };

    let mut total: u64 = 0;
    let mut all_ok = true;

    for arg in &args {
        let name = arg.to_string_lossy();
        match count_file(&cwd, Path::new(arg)) {
            Ok(n) => {
                println!("{} {}", n, name);
                total += n;
            }
            Err(()) => {
                eprintln!("error: {}", name);
                all_ok = false;
            }
        }
    }

    println!("total {}", total);
    process::exit(if all_ok { 0 } else { 1 });
}

use std::collections::HashMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};

fn rel_name(root: &Path, p: &Path) -> Result<String, String> {
    let rel = p
        .strip_prefix(root)
        .map_err(|_| "file is outside DIR".to_string())?;
    let mut parts: Vec<&str> = Vec::new();
    for comp in rel.components() {
        match comp.as_os_str().to_str() {
            Some(s) => parts.push(s),
            None => return Err("file name is not valid UTF-8".to_string()),
        }
    }
    Ok(parts.join("/"))
}

fn run() -> Result<String, String> {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 1 {
        return Err("usage: PROGRAM DIR".to_string());
    }

    let cwd = env::current_dir()
        .map_err(|e| format!("cannot determine current directory: {}", e))?;
    let cwd = fs::canonicalize(&cwd)
        .map_err(|e| format!("cannot resolve current directory: {}", e))?;

    let root = fs::canonicalize(&args[0])
        .map_err(|_| "DIR is not an existing folder".to_string())?;
    if !root.is_dir() {
        return Err("DIR is not an existing folder".to_string());
    }
    if !root.starts_with(&cwd) {
        return Err("DIR is outside the current working directory".to_string());
    }

    // Walk the tree without following symbolic links.
    let mut by_size: HashMap<u64, Vec<PathBuf>> = HashMap::new();
    let mut stack: Vec<PathBuf> = vec![root.clone()];
    while let Some(dir) = stack.pop() {
        let entries = fs::read_dir(&dir)
            .map_err(|e| format!("cannot read folder {}: {}", dir.display(), e))?;
        for entry in entries {
            let entry = entry.map_err(|e| format!("cannot read entry: {}", e))?;
            let ft = entry
                .file_type()
                .map_err(|e| format!("cannot inspect {}: {}", entry.path().display(), e))?;
            let p = entry.path();
            if ft.is_dir() {
                stack.push(p);
            } else if ft.is_file() {
                let len = entry
                    .metadata()
                    .map_err(|e| format!("cannot stat {}: {}", p.display(), e))?
                    .len();
                by_size.entry(len).or_default().push(p);
            }
        }
    }

    let mut lines: Vec<String> = Vec::new();
    for (_, group) in by_size.into_iter() {
        if group.len() < 2 {
            continue;
        }
        let mut by_content: HashMap<Vec<u8>, Vec<PathBuf>> = HashMap::new();
        for p in group {
            let data = fs::read(&p)
                .map_err(|e| format!("cannot read {}: {}", p.display(), e))?;
            by_content.entry(data).or_default().push(p);
        }
        for (_, paths) in by_content.into_iter() {
            if paths.len() < 2 {
                continue;
            }
            let mut names: Vec<String> = Vec::with_capacity(paths.len());
            for p in &paths {
                names.push(rel_name(&root, p)?);
            }
            names.sort();
            lines.push(names.join(" "));
        }
    }

    lines.sort();
    let mut out = String::new();
    for line in lines {
        out.push_str(&line);
        out.push('\n');
    }
    Ok(out)
}

fn main() {
    match run() {
        Ok(out) => {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            if handle.write_all(out.as_bytes()).is_err() || handle.flush().is_err() {
                eprintln!("error: cannot write to standard output");
                std::process::exit(1);
            }
            std::process::exit(0);
        }
        Err(msg) => {
            eprintln!("error: {}", msg);
            std::process::exit(1);
        }
    }
}

use std::collections::HashMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn is_name_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn resolve_inside(cwd: &Path, arg: &str) -> PathBuf {
    let resolved = match fs::canonicalize(arg) {
        Ok(p) => p,
        Err(_) => fail(&format!("cannot read file: {}", arg)),
    };
    if !resolved.starts_with(cwd) {
        fail(&format!("path is outside the working directory: {}", arg));
    }
    resolved
}

fn read_file(path: &Path, arg: &str) -> String {
    match fs::read_to_string(path) {
        Ok(s) => s,
        Err(_) => fail(&format!("cannot read file as UTF-8 text: {}", arg)),
    }
}

fn parse_vars(text: &str) -> HashMap<String, String> {
    let mut vars = HashMap::new();
    for line in text.split('\n') {
        if line.is_empty() {
            continue;
        }
        let eq = match line.find('=') {
            Some(i) => i,
            None => fail("malformed VARS line: missing '='"),
        };
        let name = &line[..eq];
        if name.is_empty() || !name.bytes().all(is_name_byte) {
            fail("malformed VARS line: invalid NAME");
        }
        let value = &line[eq + 1..];
        vars.insert(name.to_string(), value.to_string());
    }
    vars
}

fn render(template: &str, vars: &HashMap<String, String>) -> String {
    let bytes = template.as_bytes();
    let len = bytes.len();
    let mut out = String::with_capacity(template.len());
    let mut last = 0usize;
    let mut i = 0usize;

    while i < len {
        if bytes[i..].starts_with(b"{{") {
            let start = i + 2;
            let mut j = start;
            while j < len && is_name_byte(bytes[j]) {
                j += 1;
            }
            if j > start && bytes[j..].starts_with(b"}}") {
                let name = &template[start..j];
                let value = match vars.get(name) {
                    Some(v) => v,
                    None => fail(&format!("template uses undefined NAME: {}", name)),
                };
                out.push_str(&template[last..i]);
                out.push_str(value);
                i = j + 2;
                last = i;
                continue;
            }
        }
        i += 1;
    }
    out.push_str(&template[last..]);
    out
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        fail("usage: PROGRAM TEMPLATE VARS");
    }
    let mut strs: Vec<String> = Vec::with_capacity(2);
    for a in &args {
        match a.to_str() {
            Some(s) => strs.push(s.to_string()),
            None => fail("argument is not valid UTF-8"),
        }
    }

    let cwd_raw = match env::current_dir() {
        Ok(p) => p,
        Err(_) => fail("cannot determine working directory"),
    };
    let cwd = match fs::canonicalize(&cwd_raw) {
        Ok(p) => p,
        Err(_) => fail("cannot resolve working directory"),
    };

    let template_path = resolve_inside(&cwd, &strs[0]);
    let vars_path = resolve_inside(&cwd, &strs[1]);

    let template = read_file(&template_path, &strs[0]);
    let vars_text = read_file(&vars_path, &strs[1]);

    let vars = parse_vars(&vars_text);
    let mut output = render(&template, &vars);
    if !output.is_empty() && !output.ends_with('\n') {
        output.push('\n');
    }

    let stdout = io::stdout();
    let mut lock = stdout.lock();
    if lock.write_all(output.as_bytes()).is_err() || lock.flush().is_err() {
        fail("cannot write to standard output");
    }
    process::exit(0);
}

import * as fs from "node:fs";
import * as path from "node:path";

const USAGE = "no FILE given; usage: PROGRAM FILE...";

function realOf(p: string, depth: number = 0): string {
  const abs = path.resolve(p);
  try {
    return fs.realpathSync(abs);
  } catch {
    // Not fully resolvable; resolve as far as possible below.
  }
  const parent = path.dirname(abs);
  if (parent === abs) {
    return abs;
  }
  try {
    if (fs.lstatSync(abs).isSymbolicLink() && depth < 40) {
      return realOf(path.resolve(parent, fs.readlinkSync(abs)), depth + 1);
    }
  } catch {
    // Not a symbolic link; fall through.
  }
  return path.join(realOf(parent, depth), path.basename(abs));
}

function isInside(real: string, root: string): boolean {
  const rel = path.relative(root, real);
  if (rel === "") {
    return true;
  }
  return rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel);
}

function countLines(buf: Buffer): number {
  let n = 0;
  let pos = buf.indexOf(10);
  while (pos !== -1) {
    n++;
    pos = buf.indexOf(10, pos + 1);
  }
  if (buf.length > 0 && buf[buf.length - 1] !== 10) {
    n++;
  }
  return n;
}

function main(): void {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    process.stderr.write(`error: ${USAGE}\n`);
    process.exitCode = 1;
    return;
  }

  const root = fs.realpathSync(process.cwd());

  // Validate every argument before any output so that a failure leaves stdout empty.
  for (const arg of args) {
    if (!isInside(realOf(arg), root)) {
      process.stderr.write(`error: ${arg}: outside the current directory\n`);
      process.exitCode = 1;
      return;
    }
  }

  let sum = 0;
  let allCounted = true;

  for (const arg of args) {
    let count: number | undefined = undefined;
    try {
      if (fs.statSync(arg).isFile()) {
        count = countLines(fs.readFileSync(arg));
      }
    } catch {
      count = undefined;
    }

    if (count === undefined) {
      process.stderr.write(`error: ${arg}\n`);
      allCounted = false;
    } else {
      process.stdout.write(`${count} ${arg}\n`);
      sum += count;
    }
  }

  process.stdout.write(`total ${sum}\n`);
  process.exitCode = allCounted ? 0 : 1;
}

main();

import * as fs from "node:fs";
import * as path from "node:path";

const USAGE = "no FILE given; usage: PROGRAM FILE...";
const MAX_LINKS = 40;

function isInside(p: string, root: string): boolean {
  const prefix = root.endsWith(path.sep) ? root : root + path.sep;
  return p === root || p.startsWith(prefix);
}

// Resolves `arg` component by component, following ".." and symbolic links in
// the order the operating system would. Returns null when the path cannot be
// resolved safely inside `root`; the caller still checks the final result.
function resolveInside(arg: string, root: string): string | null {
  let cur = path.isAbsolute(arg) ? path.parse(arg).root : root;
  const queue: string[] = arg.split(path.sep);
  let links = 0;

  while (queue.length > 0) {
    const comp = queue.shift() ?? "";
    if (comp === "" || comp === ".") {
      continue;
    }
    if (comp === "..") {
      cur = path.dirname(cur);
      continue;
    }
    // Never inspect entries of directories outside the working directory.
    if (!isInside(cur, root)) {
      return null;
    }
    const next = path.join(cur, comp);
    let st: fs.Stats;
    try {
      st = fs.lstatSync(next);
    } catch {
      // Does not exist (or cannot be inspected): nothing further can be a link.
      cur = next;
      continue;
    }
    if (st.isSymbolicLink()) {
      links++;
      if (links > MAX_LINKS) {
        return null;
      }
      const target = fs.readlinkSync(next);
      if (path.isAbsolute(target)) {
        cur = path.parse(target).root;
      }
      queue.unshift(...target.split(path.sep));
      continue;
    }
    cur = next;
  }
  return cur;
}

function countLines(buf: Buffer): number {
  let n = 0;
  let pos = buf.indexOf(10);
  while (pos !== -1) {
    n++;
    pos = buf.indexOf(10, pos + 1);
  }
  if (buf.length > 0 && buf[buf.length - 1] !== 10) {
    n++;
  }
  return n;
}

function countArg(arg: string, root: string): number | null {
  const real = resolveInside(arg, root);
  if (real === null || !isInside(real, root)) {
    return null;
  }
  try {
    const st = fs.statSync(real);
    if (!st.isFile()) {
      return null;
    }
    return countLines(fs.readFileSync(real));
  } catch {
    return null;
  }
}

function main(): void {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    process.stderr.write(`error: ${USAGE}\n`);
    process.exitCode = 1;
    return;
  }

  const root = fs.realpathSync(process.cwd());
  let sum = 0;
  let allCounted = true;

  for (const arg of args) {
    const count = countArg(arg, root);
    if (count === null) {
      process.stderr.write(`error: ${arg}\n`);
      allCounted = false;
    } else {
      process.stdout.write(`${count} ${arg}\n`);
      sum += count;
    }
  }

  process.stdout.write(`total ${sum}\n`);
  process.exitCode = allCounted ? 0 : 1;
}

main();

use std::collections::BTreeMap;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn parse_qty(s: &str) -> Option<u64> {
    if s.is_empty() || !s.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    s.parse::<u64>().ok()
}

// Returns (is_restock, magnitude). A leading '-' marks a restock.
// Magnitude must be at least 1, so "0" and "-0" are malformed.
fn parse_order_qty(s: &str) -> Option<(bool, u64)> {
    if let Some(rest) = s.strip_prefix('-') {
        match parse_qty(rest) {
            Some(q) if q >= 1 => Some((true, q)),
            _ => None,
        }
    } else {
        match parse_qty(s) {
            Some(q) if q >= 1 => Some((false, q)),
            _ => None,
        }
    }
}

fn resolve(arg: &OsString, cwd: &Path) -> PathBuf {
    let shown = format!("{:?}", arg);
    let p = match fs::canonicalize(arg) {
        Ok(p) => p,
        Err(_) => fail(&format!("cannot read {}", shown)),
    };
    if !p.starts_with(cwd) {
        fail(&format!("path outside working directory: {}", shown));
    }
    p
}

fn read_file(p: &Path) -> String {
    match fs::read_to_string(p) {
        Ok(s) => s,
        Err(_) => fail(&format!("cannot read {:?}", p.display().to_string())),
    }
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        fail("usage: PROGRAM STOCK ORDERS");
    }

    let cwd = match env::current_dir().and_then(fs::canonicalize) {
        Ok(p) => p,
        Err(_) => fail("cannot determine working directory"),
    };

    let stock_path = resolve(&args[0], &cwd);
    let orders_path = resolve(&args[1], &cwd);

    let stock_text = read_file(&stock_path);
    let orders_text = read_file(&orders_path);

    // Parse STOCK.
    let mut stock: BTreeMap<String, u64> = BTreeMap::new();
    for line in stock_text.lines() {
        let toks: Vec<&str> = line.split_whitespace().collect();
        if toks.is_empty() {
            continue;
        }
        if toks.len() != 2 {
            fail("malformed line in STOCK");
        }
        let qty = match parse_qty(toks[1]) {
            Some(q) => q,
            None => fail("malformed line in STOCK"),
        };
        if stock.contains_key(toks[0]) {
            fail("duplicate item in STOCK");
        }
        stock.insert(toks[0].to_string(), qty);
    }

    // Apply ORDERS in memory; nothing is written until all succeed.
    let mut applied: u64 = 0;
    for (i, line) in orders_text.lines().enumerate() {
        let n = i + 1;
        let toks: Vec<&str> = line.split_whitespace().collect();
        if toks.is_empty() {
            continue;
        }
        if toks.len() != 2 {
            fail(&format!("line {}", n));
        }
        let (restock, qty) = match parse_order_qty(toks[1]) {
            Some(v) => v,
            None => fail(&format!("line {}", n)),
        };
        match stock.get_mut(toks[0]) {
            None => fail(&format!("line {}", n)),
            Some(left) => {
                if restock {
                    *left = match left.checked_add(qty) {
                        Some(v) => v,
                        None => fail(&format!("line {}", n)),
                    };
                } else {
                    if qty > *left {
                        fail(&format!("line {}", n));
                    }
                    *left -= qty;
                }
            }
        }
        applied += 1;
    }

    // Build the new STOCK contents (BTreeMap iterates in byte/code-point order).
    let mut out = String::new();
    for (item, qty) in &stock {
        out.push_str(item);
        out.push(' ');
        out.push_str(&qty.to_string());
        out.push('\n');
    }

    if fs::write(&stock_path, out.as_bytes()).is_err() {
        fail(&format!("cannot write {:?}", stock_path.display().to_string()));
    }

    println!("ok {}", applied);
    process::exit(0);
}

use std::collections::HashSet;
use std::env;
use std::ffi::{OsStr, OsString};
use std::fs;
use std::os::unix::ffi::{OsStrExt, OsStringExt};
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn exists(p: &Path) -> bool {
    fs::symlink_metadata(p).is_ok()
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.is_empty() || args.len() > 2 {
        fail("usage: PROGRAM DIR [--apply]");
    }
    let apply = if args.len() == 2 {
        if args[1].as_os_str() != OsStr::new("--apply") {
            fail("second argument must be --apply");
        }
        true
    } else {
        false
    };

    let cwd = fs::canonicalize(".").unwrap_or_else(|_| fail("cannot resolve current directory"));

    let dir_arg = PathBuf::from(&args[0]);
    let dir = fs::canonicalize(&dir_arg).unwrap_or_else(|_| fail("DIR is not an existing folder"));
    if !dir.is_dir() {
        fail("DIR is not an existing folder");
    }
    if !dir.starts_with(&cwd) {
        fail("DIR is outside the current working directory");
    }

    let rd = fs::read_dir(&dir).unwrap_or_else(|_| fail("cannot read DIR"));
    let mut names: Vec<OsString> = Vec::new();
    for entry in rd {
        let entry = entry.unwrap_or_else(|_| fail("cannot read DIR"));
        let ft = entry
            .file_type()
            .unwrap_or_else(|_| fail("cannot read entry type"));
        if !ft.is_file() {
            continue;
        }
        let name = entry.file_name();
        if name.as_bytes().contains(&b' ') {
            names.push(name);
        }
    }
    names.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));

    // Plan everything first, simulating the sequence of renames so that
    // dry-run output matches what --apply would do.
    let mut plan: Vec<(OsString, OsString, bool)> = Vec::new();
    let mut taken: HashSet<Vec<u8>> = HashSet::new();
    for old in &names {
        let new_bytes: Vec<u8> = old
            .as_bytes()
            .iter()
            .map(|&b| if b == b' ' { b'_' } else { b })
            .collect();
        let new = OsString::from_vec(new_bytes.clone());
        let conflict = taken.contains(&new_bytes) || exists(&dir.join(&new));
        if !conflict {
            taken.insert(new_bytes);
        }
        plan.push((old.clone(), new, conflict));
    }

    if apply {
        let mut done: Vec<(PathBuf, PathBuf)> = Vec::new();
        let mut failure: Option<String> = None;
        for (old, new, conflict) in &plan {
            if *conflict {
                continue;
            }
            let from = dir.join(old);
            let to = dir.join(new);
            if exists(&to) {
                failure = Some(format!(
                    "target appeared during run: {}",
                    new.to_string_lossy()
                ));
                break;
            }
            if let Err(e) = fs::rename(&from, &to) {
                failure = Some(format!(
                    "cannot rename {}: {}",
                    old.to_string_lossy(),
                    e
                ));
                break;
            }
            done.push((from, to));
        }
        if let Some(msg) = failure {
            for (from, to) in done.iter().rev() {
                let _ = fs::rename(to, from);
            }
            fail(&msg);
        }
    }

    for (old, new, conflict) in &plan {
        if *conflict {
            println!("conflict: {}", old.to_string_lossy());
        } else {
            println!("{} -> {}", old.to_string_lossy(), new.to_string_lossy());
        }
    }

    process::exit(0);
}

package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

type entry struct {
	word  string
	count int
}

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	os.Exit(1)
}

// parseN accepts only a string of ASCII digits denoting an integer >= 1.
func parseN(s string) (int, bool) {
	if s == "" {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	v, err := strconv.Atoi(s)
	if err != nil || v < 1 {
		return 0, false
	}
	return v, true
}

// resolveInside returns the symlink-free absolute path of name and
// reports an error unless that path lies inside the current directory.
func resolveInside(name string) (string, error) {
	if name == "" {
		return "", fmt.Errorf("empty file name")
	}
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		return "", err
	}
	abs := name
	if !filepath.IsAbs(abs) {
		abs = filepath.Join(cwdReal, abs)
	}
	real, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return "", err
	}
	rel, err := filepath.Rel(cwdReal, real)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		return "", fmt.Errorf("%s is outside the current directory", name)
	}
	return real, nil
}

func main() {
	args := os.Args[1:]
	if len(args) != 2 {
		fail("usage: PROGRAM FILE N")
	}

	n, ok := parseN(args[1])
	if !ok {
		fail("N must be a whole number of at least 1 written in digits")
	}

	path, err := resolveInside(args[0])
	if err != nil {
		fail(err.Error())
	}

	data, err := os.ReadFile(path)
	if err != nil {
		fail(fmt.Sprintf("cannot read %s: %v", args[0], err))
	}

	counts := make(map[string]int)
	buf := make([]byte, 0, 32)
	flush := func() {
		if len(buf) > 0 {
			counts[string(buf)]++
			buf = buf[:0]
		}
	}
	for _, b := range data {
		switch {
		case b >= 'a' && b <= 'z':
			buf = append(buf, b)
		case b >= 'A' && b <= 'Z':
			buf = append(buf, b+('a'-'A'))
		default:
			flush()
		}
	}
	flush()

	entries := make([]entry, 0, len(counts))
	for w, c := range counts {
		entries = append(entries, entry{word: w, count: c})
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].count != entries[j].count {
			return entries[i].count > entries[j].count
		}
		return entries[i].word < entries[j].word
	})

	var out strings.Builder
	for i := 0; i < min(n, len(entries)); i++ {
		fmt.Fprintf(&out, "%s %d\n", entries[i].word, entries[i].count)
	}
	os.Stdout.WriteString(out.String())
	os.Exit(0)
}

use std::env;
use std::ffi::OsString;
use std::fs::{self, File};
use std::io::{self, Read};
use std::path::Path;
use std::process;

fn count_lines(file: &mut File) -> io::Result<u64> {
    let mut buf = [0u8; 65536];
    let mut count: u64 = 0;
    let mut last: Option<u8> = None;
    loop {
        let n = match file.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        };
        count += buf[..n].iter().filter(|&&b| b == b'\n').count() as u64;
        last = Some(buf[n - 1]);
    }
    if let Some(b) = last {
        if b != b'\n' {
            count += 1;
        }
    }
    Ok(count)
}

fn count_words(file: &mut File) -> io::Result<u64> {
    let mut data: Vec<u8> = Vec::new();
    file.read_to_end(&mut data)?;
    let text = String::from_utf8_lossy(&data);
    Ok(text.split_whitespace().count() as u64)
}

fn count_file(cwd: &Path, path: &Path, words: bool) -> Result<u64, ()> {
    let resolved = fs::canonicalize(path).map_err(|_| ())?;
    if !resolved.starts_with(cwd) {
        return Err(());
    }
    let meta = fs::metadata(&resolved).map_err(|_| ())?;
    if !meta.is_file() {
        return Err(());
    }
    let mut f = File::open(&resolved).map_err(|_| ())?;
    if words {
        count_words(&mut f).map_err(|_| ())
    } else {
        count_lines(&mut f).map_err(|_| ())
    }
}

fn main() {
    let mut args: Vec<OsString> = env::args_os().skip(1).collect();

    let words = if args.first().and_then(|a| a.to_str()) == Some("--words") {
        args.remove(0);
        true
    } else {
        false
    };

    if args.is_empty() {
        eprintln!("error: no FILE given");
        process::exit(1);
    }

    let cwd = match env::current_dir().and_then(fs::canonicalize) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("error: cannot determine current directory: {}", e);
            process::exit(1);
        }
    };

    let mut total: u64 = 0;
    let mut all_ok = true;

    for arg in &args {
        let name = arg.to_string_lossy();
        match count_file(&cwd, Path::new(arg), words) {
            Ok(n) => {
                println!("{} {}", n, name);
                total += n;
            }
            Err(()) => {
                eprintln!("error: {}", name);
                all_ok = false;
            }
        }
    }

    println!("total {}", total);
    process::exit(if all_ok { 0 } else { 1 });
}

use std::collections::HashSet;
use std::env;
use std::ffi::OsString;
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn resolve_inside(cwd: &Path, arg: &PathBuf, must_exist: bool) -> Result<PathBuf, String> {
    let shown = arg.display();
    let resolved = match fs::canonicalize(arg) {
        Ok(r) => r,
        Err(e) => {
            if must_exist {
                return Err(format!("cannot read {}: {}", shown, e));
            }
            // A path that exists as a link but cannot be resolved (e.g. dangling) is refused.
            if fs::symlink_metadata(arg).is_ok() {
                return Err(format!("cannot resolve {}", shown));
            }
            let name = arg
                .file_name()
                .ok_or_else(|| format!("invalid output path {}", shown))?;
            let parent = match arg.parent() {
                Some(p) if !p.as_os_str().is_empty() => p,
                _ => Path::new("."),
            };
            let parent_resolved = fs::canonicalize(parent)
                .map_err(|e| format!("cannot write {}: {}", shown, e))?;
            parent_resolved.join(name)
        }
    };
    if !resolved.starts_with(cwd) {
        return Err(format!("path outside working directory: {}", shown));
    }
    Ok(resolved)
}

fn run(args: &[OsString]) -> Result<(usize, usize), String> {
    let cwd = env::current_dir()
        .and_then(|d| d.canonicalize())
        .map_err(|e| format!("cannot determine working directory: {}", e))?;

    let in_arg = PathBuf::from(&args[0]);
    let out_arg = PathBuf::from(&args[1]);

    let in_path = resolve_inside(&cwd, &in_arg, true)?;
    let out_path = resolve_inside(&cwd, &out_arg, false)?;

    let text = fs::read_to_string(&in_path)
        .map_err(|e| format!("cannot read {}: {}", in_arg.display(), e))?;

    let lines: Vec<&str> = if text.is_empty() {
        Vec::new()
    } else {
        text.strip_suffix('\n')
            .unwrap_or(text.as_str())
            .split('\n')
            .collect()
    };

    let total = lines.len();
    let mut seen: HashSet<&str> = HashSet::new();
    let mut out = String::new();
    let mut kept = 0usize;
    for line in lines {
        if seen.insert(line) {
            out.push_str(line);
            out.push('\n');
            kept += 1;
        }
    }
    let dropped = total - kept;

    let mut file = OpenOptions::new()
        .write(true)
        .create(true)
        .open(&out_path)
        .map_err(|e| format!("cannot write {}: {}", out_arg.display(), e))?;
    file.set_len(0)
        .map_err(|e| format!("cannot write {}: {}", out_arg.display(), e))?;
    file.write_all(out.as_bytes())
        .map_err(|e| format!("cannot write {}: {}", out_arg.display(), e))?;

    Ok((kept, dropped))
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 2 {
        fail("usage: PROGRAM IN OUT");
    }
    match run(&args) {
        Ok((kept, dropped)) => println!("kept {} dropped {}", kept, dropped),
        Err(msg) => fail(&msg),
    }
}

import * as fs from "node:fs";
import * as path from "node:path";

const USAGE = "no FILE given; usage: PROGRAM [--words] FILE...";
const MAX_LINKS = 40;

function isInside(p: string, root: string): boolean {
  const prefix = root.endsWith(path.sep) ? root : root + path.sep;
  return p === root || p.startsWith(prefix);
}

// Resolves `arg` component by component, following ".." and symbolic links in
// the order the operating system would. Returns null when the path cannot be
// resolved safely inside `root`; the caller still checks the final result.
function resolveInside(arg: string, root: string): string | null {
  let cur = path.isAbsolute(arg) ? path.parse(arg).root : root;
  const queue: string[] = arg.split(path.sep);
  let links = 0;

  while (queue.length > 0) {
    const comp = queue.shift() ?? "";
    if (comp === "" || comp === ".") {
      continue;
    }
    if (comp === "..") {
      cur = path.dirname(cur);
      continue;
    }
    // Never inspect entries of directories outside the working directory.
    if (!isInside(cur, root)) {
      return null;
    }
    const next = path.join(cur, comp);
    let st: fs.Stats;
    try {
      st = fs.lstatSync(next);
    } catch {
      // Does not exist (or cannot be inspected): nothing further can be a link.
      cur = next;
      continue;
    }
    if (st.isSymbolicLink()) {
      links++;
      if (links > MAX_LINKS) {
        return null;
      }
      const target = fs.readlinkSync(next);
      if (path.isAbsolute(target)) {
        cur = path.parse(target).root;
      }
      queue.unshift(...target.split(path.sep));
      continue;
    }
    cur = next;
  }
  return cur;
}

function countLines(buf: Buffer): number {
  let n = 0;
  let pos = buf.indexOf(10);
  while (pos !== -1) {
    n++;
    pos = buf.indexOf(10, pos + 1);
  }
  if (buf.length > 0 && buf[buf.length - 1] !== 10) {
    n++;
  }
  return n;
}

function countWords(buf: Buffer): number {
  const text = buf.toString("utf8");
  const matches = text.match(/\S+/g);
  return matches === null ? 0 : matches.length;
}

function countArg(arg: string, root: string, words: boolean): number | null {
  const real = resolveInside(arg, root);
  if (real === null || !isInside(real, root)) {
    return null;
  }
  try {
    const st = fs.statSync(real);
    if (!st.isFile()) {
      return null;
    }
    const buf = fs.readFileSync(real);
    return words ? countWords(buf) : countLines(buf);
  } catch {
    return null;
  }
}

function main(): void {
  let args = process.argv.slice(2);

  let words = false;
  if (args[0] === "--words") {
    words = true;
    args = args.slice(1);
  }

  if (args.length === 0) {
    process.stderr.write(`error: ${USAGE}\n`);
    process.exitCode = 1;
    return;
  }

  const root = fs.realpathSync(process.cwd());
  let sum = 0;
  let allCounted = true;

  for (const arg of args) {
    const count = countArg(arg, root, words);
    if (count === null) {
      process.stderr.write(`error: ${arg}\n`);
      allCounted = false;
    } else {
      process.stdout.write(`${count} ${arg}\n`);
      sum += count;
    }
  }

  process.stdout.write(`total ${sum}\n`);
  process.exitCode = allCounted ? 0 : 1;
}

main();

