func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", msg)
	os.Exit(1)
}

func main() {
	if len(os.Args) > 1 {
		fail("unexpected arguments; usage: program takes no arguments and reads standard input")
	}

	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		fail("reading standard input: " + err.Error())
	}

	levels := []string{"DEBUG", "INFO", "WARN", "ERROR"}
	counts := make(map[string]int, len(levels))
	malformed := 0

	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSuffix(line, "\r")
		if line == "" {
			continue
		}

		matched := false
		for _, lv := range levels {
			prefix := lv + " "
			if strings.HasPrefix(line, prefix) {
				rest := line[len(prefix):]
				if utf8.RuneCountInString(rest) > 0 {
					counts[lv]++
					matched = true
				}
				break
			}
		}
		if !matched {
			malformed++
		}
	}

	out := bufio.NewWriter(os.Stdout)
	for _, lv := range levels {
		if counts[lv] > 0 {
			fmt.Fprintf(out, "%s %d\n", lv, counts[lv])
		}
	}
	if malformed > 0 {
		fmt.Fprintf(out, "MALFORMED %d\n", malformed)
	}
	if err := out.Flush(); err != nil {
		fail("writing standard output: " + err.Error())
	}
	os.Exit(0)
}

