)

func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", msg)
	os.Exit(1)
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func resolveInside(arg, cwdResolved string) string {
	abs, err := filepath.Abs(arg)
	if err != nil {
		fail("cannot resolve path " + arg)
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		fail("cannot read " + arg)
	}
	rel, err := filepath.Rel(cwdResolved, resolved)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		fail("path outside working directory: " + arg)
	}
	return resolved
}

func main() {
	if len(os.Args) != 3 {
		fail("usage: PROGRAM STOCK ORDERS")
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdResolved, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot determine working directory")
	}

	stockPath := resolveInside(os.Args[1], cwdResolved)
	ordersPath := resolveInside(os.Args[2], cwdResolved)

	stockData, err := os.ReadFile(stockPath)
	if err != nil {
		fail("cannot read stock file")
	}
	ordersData, err := os.ReadFile(ordersPath)
	if err != nil {
		fail("cannot read orders file")
	}

	stock := make(map[string]int64)
	for _, line := range strings.Split(string(stockData), "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if len(fields) != 2 || !utf8.ValidString(line) || !isDigits(fields[1]) {
			fail("malformed stock line")
		}
		q, err := strconv.ParseInt(fields[1], 10, 64)
		if err != nil {
			fail("malformed stock line")
		}
		name := fields[0]
		if _, dup := stock[name]; dup {
			fail("duplicate item in stock: " + name)
		}
		stock[name] = q
	}

	applied := 0
	for i, line := range strings.Split(string(ordersData), "\n") {
		n := i + 1
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if len(fields) != 2 || !utf8.ValidString(line) || !isDigits(fields[1]) {
			fail(fmt.Sprintf("line %d", n))
		}
		q, err := strconv.ParseInt(fields[1], 10, 64)
		if err != nil || q < 1 {
			fail(fmt.Sprintf("line %d", n))
		}
		name := fields[0]
		cur, ok := stock[name]
		if !ok {
			fail(fmt.Sprintf("line %d", n))
		}
		if q > cur {
			fail(fmt.Sprintf("line %d", n))
		}
		stock[name] = cur - q
		applied++
	}

	names := make([]string, 0, len(stock))
	for name := range stock {
		names = append(names, name)
	}
	sort.Strings(names)

	var b strings.Builder
	for _, name := range names {
		fmt.Fprintf(&b, "%s %d\n", name, stock[name])
	}
	if err := os.WriteFile(stockPath, []byte(b.String()), 0644); err != nil {
		fail("cannot write stock file")
	}

	fmt.Printf("ok %d\n", applied)
}

use std::collections::VecDeque;
use std::env;
use std::ffi::OsString;
use std::fs;
use std::io::{self, Write};
use std::path::{Component, Path, PathBuf};
use std::process;

enum Comp {
    Name(OsString),
    Up,
}

enum Resolved {
    Outside,
    Inside { path: PathBuf, missing: bool },
}

fn to_comps(p: &Path) -> Option<Vec<Comp>> {
    let mut v = Vec::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            Component::ParentDir => v.push(Comp::Up),
            Component::Normal(s) => v.push(Comp::Name(s.to_os_string())),
            _ => return None,
        }
    }
    Some(v)
}

fn join_stack(cwd: &Path, stack: &[(OsString, bool)]) -> PathBuf {
    let mut p = cwd.to_path_buf();
    for (s, _) in stack {
        p.push(s);
    }
    p
}

// `cwd` must be canonical. Resolves `rel` physically (following symlinks)
// and reports whether the result lies inside `cwd`.
fn resolve(cwd: &Path, rel: &Path) -> Resolved {
    let comps = match to_comps(rel) {
        Some(c) => c,
        None => return Resolved::Outside,
    };
    let mut pending: VecDeque<Comp> = VecDeque::from(comps);
    let mut stack: Vec<(OsString, bool)> = Vec::new();
    let mut missing = false;
    let mut hops: u32 = 0;

    while let Some(c) = pending.pop_front() {
        match c {
            Comp::Up => match stack.pop() {
                None => return Resolved::Outside,
                Some((_, is_dir)) => {
                    if !is_dir {
                        missing = true;
                    }
                }
            },
            Comp::Name(s) => {
                let p = join_stack(cwd, &stack).join(&s);
                match fs::symlink_metadata(&p) {
                    Err(_) => {
                        stack.push((s, false));
                        missing = true;
                    }
                    Ok(md) if md.file_type().is_symlink() => {
                        hops += 1;
                        if hops > 40 {
                            return Resolved::Inside {
                                path: join_stack(cwd, &stack),
                                missing: true,
                            };
                        }
                        let target = match fs::read_link(&p) {
                            Ok(t) => t,
                            Err(_) => {
                                return Resolved::Inside {
                                    path: join_stack(cwd, &stack),
                                    missing: true,
                                }
                            }
                        };
                        let rest: PathBuf = if target.is_absolute() {
                            match target.strip_prefix(cwd) {
                                Ok(r) => {
                                    stack.clear();
                                    r.to_path_buf()
                                }
                                Err(_) => return Resolved::Outside,
                            }
                        } else {
                            target
                        };
                        let new_comps = match to_comps(&rest) {
                            Some(c) => c,
                            None => return Resolved::Outside,
                        };
                        for nc in new_comps.into_iter().rev() {
                            pending.push_front(nc);
                        }
                    }
                    Ok(md) => stack.push((s, md.is_dir())),
                }
            }
        }
    }

    Resolved::Inside {
        path: join_stack(cwd, &stack),
        missing,
    }
}

fn run() -> Result<String, String> {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 1 {
        return Err("usage: PROGRAM LIST".to_string());
    }

    let cwd_raw = env::current_dir()
        .map_err(|e| format!("cannot determine working directory: {}", e))?;
    let cwd = fs::canonicalize(&cwd_raw)
        .map_err(|e| format!("cannot resolve working directory: {}", e))?;

    let list_arg = PathBuf::from(args[0].clone());
    let list_path = match resolve(&cwd, &list_arg) {
        Resolved::Outside => {
            return Err(format!(
                "{} is outside the working directory",
                list_arg.display()
            ))
        }
        Resolved::Inside { path, .. } => path,
    };
    let list_text = fs::read_to_string(&list_path)
        .map_err(|e| format!("cannot read {}: {}", list_arg.display(), e))?;

    let mut out = String::new();
    for name in list_text.lines() {
        if name.is_empty() {
            continue;
        }
        match resolve(&cwd, Path::new(name)) {
            Resolved::Outside => {
                out.push_str("skipped: ");
                out.push_str(name);
                out.push('\n');
            }
            Resolved::Inside { path, missing } => {
                let is_file = !missing
                    && fs::metadata(&path)
                        .map(|m| m.is_file())
                        .unwrap_or(false);
                if !is_file {
                    out.push_str("missing: ");
                    out.push_str(name);
                    out.push('\n');
                    continue;
                }
                let bytes = fs::read(&path)
                    .map_err(|e| format!("cannot read {}: {}", name, e))?;
                let text = String::from_utf8(bytes)
                    .map_err(|_| format!("{} is not valid UTF-8", name))?;
                out.push_str("== ");
                out.push_str(name);
                out.push_str(" ==\n");
                out.push_str(&text);
                if !text.is_empty() && !text.ends_with('\n') {
                    out.push('\n');
                }
            }
        }
    }

    Ok(out)
}

fn main() {
    match run() {
        Ok(out) => {
            let stdout = io::stdout();
            let mut handle = stdout.lock();
            if handle.write_all(out.as_bytes()).is_err() {
                eprintln!("error: cannot write output");
                process::exit(1);
            }
            if handle.flush().is_err() {
                eprintln!("error: cannot write output");
                process::exit(1);
            }
            process::exit(0);
        }
        Err(msg) => {
            eprintln!("error: {}", msg);
            process::exit(1);
        }
    }
}

