	}
	name := os.Args[1]

	rawCols := strings.Split(os.Args[2], ",")
	columns := make([]string, len(rawCols))
	seen := make(map[string]bool, len(rawCols))
	for i, c := range rawCols {
		c = strings.TrimSpace(c)
		if seen[c] {
			fail("repeated column: " + c)
		}
		seen[c] = true
		columns[i] = c
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot determine working directory")
	}

	absFile, err := filepath.Abs(name)
	if err != nil {
		fail("cannot read file")
	}
	fileReal, err := filepath.EvalSymlinks(absFile)
	if err != nil {
		fail("cannot read file")
	}

	rel, err := filepath.Rel(cwdReal, fileReal)
	if err != nil || filepath.IsAbs(rel) || rel == ".." ||
		strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		fail("file is outside the current directory")
	}

	data, err := os.ReadFile(fileReal)
	if err != nil {
		fail("cannot read file")
	}

	lines := strings.Split(string(data), "\n")

	headerIdx := -1
	for i, l := range lines {
		if strings.TrimSpace(l) != "" {
			headerIdx = i
			break
		}
	}
	if headerIdx < 0 {
		fail("no header")
	}

	names := splitFields(lines[headerIdx])

	cols := make([]int, len(columns))
	for k, column := range columns {
		idx := -1
		for j, n := range names {
			if n == column {
				idx = j
				break
			}
		}
		if idx < 0 {
			fail("column not found: " + column)
		}
		cols[k] = idx
	}

	sums := make([]int64, len(columns))
	for i := headerIdx + 1; i < len(lines); i++ {
		if strings.TrimSpace(lines[i]) == "" {
			continue
		}
		lineNo := i + 1
		fields := splitFields(lines[i])
		if len(fields) != len(names) {
			fail(fmt.Sprintf("line %d", lineNo))
		}
		for k, col := range cols {
			v := fields[col]
			if !isWhole(v) {
				fail(fmt.Sprintf("line %d", lineNo))
			}
			n, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				fail(fmt.Sprintf("line %d", lineNo))
			}
			sums[k] += n
		}
	}

	if len(columns) == 1 {
		fmt.Println(sums[0])
	} else {
		for k, column := range columns {
			fmt.Printf("%s=%d\n", column, sums[k])
		}
	}
}

package main

import (
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", msg)
	os.Exit(1)
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func resolveInside(arg, cwdResolved string) string {
	abs, err := filepath.Abs(arg)
	if err != nil {
		fail("cannot resolve path " + arg)
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		fail("cannot read " + arg)
	}
	rel, err := filepath.Rel(cwdResolved, resolved)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) || filepath.IsAbs(rel) {
		fail("path outside working directory: " + arg)
	}
	return resolved
}

func main() {
	if len(os.Args) != 3 {
		fail("usage: PROGRAM STOCK ORDERS")
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdResolved, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot determine working directory")
	}

	stockPath := resolveInside(os.Args[1], cwdResolved)
	ordersPath := resolveInside(os.Args[2], cwdResolved)

	stockData, err := os.ReadFile(stockPath)
	if err != nil {
		fail("cannot read stock file")
	}
	ordersData, err := os.ReadFile(ordersPath)
	if err != nil {
		fail("cannot read orders file")
	}

	stock := make(map[string]int64)
	for _, line := range strings.Split(string(stockData), "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if len(fields) != 2 || !utf8.ValidString(line) || !isDigits(fields[1]) {
			fail("malformed stock line")
		}
		q, err := strconv.ParseInt(fields[1], 10, 64)
		if err != nil {
			fail("malformed stock line")
		}
		name := fields[0]
		if _, dup := stock[name]; dup {
			fail("duplicate item in stock: " + name)
		}
		stock[name] = q
	}

	applied := 0
	for i, line := range strings.Split(string(ordersData), "\n") {
		n := i + 1
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		if len(fields) != 2 || !utf8.ValidString(line) {
			fail(fmt.Sprintf("line %d", n))
		}
		raw := fields[1]
		neg := strings.HasPrefix(raw, "-")
		digits := raw
		if neg {
			digits = raw[1:]
		}
		if !isDigits(digits) {
			fail(fmt.Sprintf("line %d", n))
		}
		q, err := strconv.ParseInt(digits, 10, 64)
		if err != nil || q < 1 {
			fail(fmt.Sprintf("line %d", n))
		}
		name := fields[0]
		cur, ok := stock[name]
		if !ok {
			fail(fmt.Sprintf("line %d", n))
		}
		if neg {
			if cur > math.MaxInt64-q {
				fail(fmt.Sprintf("line %d", n))
			}
			stock[name] = cur + q
		} else {
			if q > cur {
				fail(fmt.Sprintf("line %d", n))
			}
			stock[name] = cur - q
		}
		applied++
	}

	names := make([]string, 0, len(stock))
	for name := range stock {
		names = append(names, name)
	}
	sort.Strings(names)

	var b strings.Builder
	for _, name := range names {
		fmt.Fprintf(&b, "%s %d\n", name, stock[name])
	}
	if err := os.WriteFile(stockPath, []byte(b.String()), 0644); err != nil {
		fail("cannot write stock file")
	}

	fmt.Printf("ok %d\n", applied)
}

package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

var errOutside = fmt.Errorf("outside working directory")

func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", msg)
	os.Exit(1)
}

// insideDir reports whether path lies within dir. Both must already be
// absolute and symlink-resolved.
func insideDir(dir, path string) bool {
	rel, err := filepath.Rel(dir, path)
	if err != nil {
		return false
	}
	if filepath.IsAbs(rel) {
		return false
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return false
	}
	return true
}

// countLines counts lines in r. A final line without a trailing newline
// still counts; an empty input has zero lines.
func countLines(r io.Reader) (int, error) {
	buf := make([]byte, 64*1024)
	newlines := 0
	total := 0
	var last byte
	for {
		m, err := r.Read(buf)
		if m > 0 {
			for _, b := range buf[:m] {
				if b == '\n' {
					newlines++
				}
			}
			last = buf[m-1]
			total += m
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return 0, err
		}
	}
	if total > 0 && last != '\n' {
		newlines++
	}
	return newlines, nil
}

// countFile returns the line count of arg if it is a readable regular file
// inside cwd (already symlink-resolved). Nothing outside cwd is read.
func countFile(arg, cwd string) (int, error) {
	abs, err := filepath.Abs(arg)
	if err != nil {
		return 0, err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return 0, err
	}
	if !insideDir(cwd, resolved) {
		return 0, errOutside
	}
	f, err := os.Open(resolved)
	if err != nil {
		return 0, err
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return 0, err
	}
	if !fi.Mode().IsRegular() {
		return 0, fmt.Errorf("not a regular file")
	}
	return countLines(f)
}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		fail("no files given")
	}

	wd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwd, err := filepath.EvalSymlinks(wd)
	if err != nil {
		fail("cannot resolve working directory")
	}

	allOK := true
	sum := 0
	for _, a := range args {
		n, err := countFile(a, cwd)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", a)
			allOK = false
			continue
		}
		fmt.Printf("%d %s\n", n, a)
		sum += n
	}
	fmt.Printf("total %d\n", sum)

	if !allOK {
		os.Exit(1)
	}
	os.Exit(0)
}

package main

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"unicode/utf8"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, "error: "+err.Error())
		os.Exit(1)
	}
}

func run(args []string) error {
	if len(args) != 3 {
		return errors.New("usage: PROGRAM A B OUT")
	}

	pa, err := insidePath(args[0])
	if err != nil {
		return err
	}
	pb, err := insidePath(args[1])
	if err != nil {
		return err
	}
	po, err := insidePath(args[2])
	if err != nil {
		return err
	}

	m := make(map[string]string)

	da, err := os.ReadFile(pa)
	if err != nil {
		return fmt.Errorf("cannot read %s: %w", args[0], err)
	}
	if err := parse(da, m, args[0]); err != nil {
		return err
	}

	db, err := os.ReadFile(pb)
	if err != nil {
		return fmt.Errorf("cannot read %s: %w", args[1], err)
	}
	if err := parse(db, m, args[1]); err != nil {
		return err
	}

	if err := writeOut(po, m); err != nil {
		return fmt.Errorf("cannot write %s: %w", args[2], err)
	}
	return nil
}

// insidePath resolves p (following symbolic links and "..") and returns the
// resulting absolute path. It fails if that path is not inside the current
// working directory.
func insidePath(p string) (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		return "", err
	}

	full := p
	if !filepath.IsAbs(full) {
		full = cwd + string(filepath.Separator) + p
	}

	cur := string(filepath.Separator)
	tail := false
	for _, c := range strings.Split(full, string(filepath.Separator)) {
		if c == "" || c == "." {
			continue
		}
		if c == ".." {
			cur = filepath.Dir(cur)
			continue
		}
		next := filepath.Join(cur, c)
		if tail {
			cur = next
			continue
		}
		fi, err := os.Lstat(next)
		if errors.Is(err, fs.ErrNotExist) {
			tail = true
			cur = next
			continue
		}
		if err != nil {
			return "", err
		}
		if fi.Mode()&fs.ModeSymlink != 0 {
			r, err := filepath.EvalSymlinks(next)
			if err != nil {
				return "", err
			}
			cur = r
		} else {
			cur = next
		}
	}

	if !isInside(cwdReal, cur) {
		return "", fmt.Errorf("path is outside the working directory: %s", p)
	}
	return cur, nil
}

func isInside(root, p string) bool {
	rel, err := filepath.Rel(root, p)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

func parse(data []byte, m map[string]string, name string) error {
	if !utf8.Valid(data) {
		return fmt.Errorf("%s: invalid UTF-8", name)
	}
	for i, line := range strings.Split(string(data), "\n") {
		if strings.TrimSpace(line) == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			return fmt.Errorf("%s: malformed line %d", name, i+1)
		}
		k = strings.TrimSpace(k)
		if k == "" {
			return fmt.Errorf("%s: empty key on line %d", name, i+1)
		}
		m[k] = strings.TrimSpace(v)
	}
	return nil
}

func writeOut(path string, m map[string]string) error {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var sb strings.Builder
	for _, k := range keys {
		sb.WriteString(k)
		sb.WriteString("=")
		sb.WriteString(m[k])
		sb.WriteString("\n")
	}

	perm := fs.FileMode(0644)
	if fi, err := os.Stat(path); err == nil {
		perm = fi.Mode().Perm()
	} else if !errors.Is(err, fs.ErrNotExist) {
		return err
	}

	tmp, err := os.CreateTemp(filepath.Dir(path), ".settings-*.tmp")
	if err != nil {
		return err
	}
	name := tmp.Name()
	committed := false
	defer func() {
		if !committed {
			_ = os.Remove(name)
		}
	}()

	if _, err := tmp.WriteString(sb.String()); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Chmod(perm); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	committed = true
	return nil
}

package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func main() {
	out, err := run(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error: "+err.Error())
		os.Exit(1)
	}
	fmt.Print(out)
}

func run(args []string) (string, error) {
	if len(args) != 2 {
		return "", errors.New("usage: PROGRAM TEMPLATE VARS")
	}

	tmplBytes, err := readInside(args[0])
	if err != nil {
		return "", err
	}
	varsBytes, err := readInside(args[1])
	if err != nil {
		return "", err
	}

	vars, err := parseVars(string(varsBytes))
	if err != nil {
		return "", err
	}

	out, err := render(string(tmplBytes), vars)
	if err != nil {
		return "", err
	}

	if out != "" && !strings.HasSuffix(out, "\n") {
		out += "\n"
	}
	return out, nil
}

// readInside reads a regular file whose fully resolved path lies inside
// the current working directory (after resolving .. and symbolic links).
func readInside(p string) ([]byte, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return nil, errors.New("cannot determine working directory")
	}
	realCwd, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		return nil, errors.New("cannot resolve working directory")
	}

	abs, err := filepath.Abs(p)
	if err != nil {
		return nil, errors.New("cannot resolve path " + strconv.Quote(p))
	}
	real, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return nil, errors.New("cannot read file " + strconv.Quote(p))
	}

	rel, err := filepath.Rel(realCwd, real)
	if err != nil || filepath.IsAbs(rel) ||
		rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return nil, errors.New("path is outside the working directory: " + strconv.Quote(p))
	}

	data, err := os.ReadFile(real)
	if err != nil {
		return nil, errors.New("cannot read file " + strconv.Quote(p))
	}
	return data, nil
}

func isNameByte(c byte) bool {
	return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
		(c >= '0' && c <= '9') || c == '_'
}

func validName(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if !isNameByte(s[i]) {
			return false
		}
	}
	return true
}

func parseVars(s string) (map[string]string, error) {
	vars := make(map[string]string)
	for i, line := range strings.Split(s, "\n") {
		if line == "" {
			continue
		}
		eq := strings.IndexByte(line, '=')
		if eq < 0 {
			return nil, fmt.Errorf("malformed VARS line %d: missing '='", i+1)
		}
		name := line[:eq]
		if !validName(name) {
			return nil, fmt.Errorf("malformed VARS line %d: invalid name", i+1)
		}
		vars[name] = line[eq+1:]
	}
	return vars, nil
}

func render(t string, vars map[string]string) (string, error) {
	var b strings.Builder
	i := 0
	for i < len(t) {
		if strings.HasPrefix(t[i:], "{{") {
			j := i + 2
			for j < len(t) && isNameByte(t[j]) {
				j++
			}
			if j > i+2 && strings.HasPrefix(t[j:], "}}") {
				name := t[i+2 : j]
				v, ok := vars[name]
				if !ok {
					return "", errors.New("template uses undefined variable " + name)
				}
				b.WriteString(v)
				i = j + 2
				continue
			}
		}
		b.WriteByte(t[i])
		i++
	}
	return b.String(), nil
}

use std::env;
use std::ffi::{OsStr, OsString};
use std::fs::{self, File, OpenOptions};
use std::io;
use std::path::{Path, PathBuf};
use std::process;

fn fail(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    process::exit(1);
}

fn exists(p: &Path) -> bool {
    fs::symlink_metadata(p).is_ok()
}

fn aux_name(name: &OsStr, suffix: &str) -> OsString {
    let mut s = OsString::new();
    s.push(name);
    s.push(suffix);
    s
}

fn make_copy(src: &Path, dst: &Path) -> io::Result<()> {
    let mut input = File::open(src)?;
    let mut output = OpenOptions::new().write(true).create_new(true).open(dst)?;
    let result = (|| -> io::Result<()> {
        io::copy(&mut input, &mut output)?;
        output.set_permissions(input.metadata()?.permissions())?;
        output.sync_all()
    })();
    if result.is_err() {
        let _ = fs::remove_file(dst);
    }
    result
}

fn move_entry(from: &Path, to: &Path, log: &mut Vec<(PathBuf, PathBuf)>) -> io::Result<()> {
    fs::rename(from, to)?;
    log.push((from.to_path_buf(), to.to_path_buf()));
    Ok(())
}

fn rollback(log: &[(PathBuf, PathBuf)], tmp: &Path) {
    for (from, to) in log.iter().rev() {
        let _ = fs::rename(to, from);
    }
    let _ = fs::remove_file(tmp);
}

fn main() {
    let args: Vec<OsString> = env::args_os().skip(1).collect();
    if args.len() != 1 {
        fail("expected exactly one argument: FILE");
    }
    let arg = PathBuf::from(&args[0]);

    let cwd = match env::current_dir().and_then(|d| d.canonicalize()) {
        Ok(d) => d,
        Err(e) => fail(&format!("cannot determine current directory: {}", e)),
    };

    let is_regular =
        |p: &Path| matches!(fs::symlink_metadata(p), Ok(m) if m.file_type().is_file());

    if !is_regular(&arg) {
        fail(&format!("{} is not an existing regular file", arg.display()));
    }

    let file = match fs::canonicalize(&arg) {
        Ok(p) => p,
        Err(e) => fail(&format!("cannot resolve {}: {}", arg.display(), e)),
    };
    if !file.starts_with(&cwd) {
        fail(&format!("{} is outside the current directory", arg.display()));
    }
    if !is_regular(&file) {
        fail(&format!("{} is not an existing regular file", arg.display()));
    }

    let (dir, name) = match (file.parent(), file.file_name()) {
        (Some(d), Some(n)) => (d.to_path_buf(), n.to_os_string()),
        _ => fail(&format!("cannot determine location of {}", arg.display())),
    };

    let bk = |n: u32| dir.join(aux_name(&name, &format!(".{}", n)));
    let b1 = bk(1);
    let b2 = bk(2);
    let b3 = bk(3);

    for p in [&b1, &b2, &b3] {
        if let Ok(m) = fs::symlink_metadata(p) {
            if !m.file_type().is_file() {
                fail(&format!("{} exists and is not a regular file", p.display()));
            }
        }
    }

    let pid = process::id();
    let mut tmp_name = OsString::from(".");
    tmp_name.push(&name);
    tmp_name.push(format!(".rotate-new-{}", pid));
    let tmp = dir.join(tmp_name);

    let mut stage_name = OsString::from(".");
    stage_name.push(&name);
    stage_name.push(format!(".rotate-old-{}", pid));
    let stage = dir.join(stage_name);

    if exists(&tmp) || exists(&stage) {
        fail("a temporary file name needed for rotation is already in use");
    }

    if let Err(e) = make_copy(&file, &tmp) {
        fail(&format!("cannot copy {}: {}", arg.display(), e));
    }

    let mut log: Vec<(PathBuf, PathBuf)> = Vec::new();
    let outcome = (|| -> io::Result<()> {
        let had3 = exists(&b3);
        if had3 {
            move_entry(&b3, &stage, &mut log)?;
        }
        if exists(&b2) {
            move_entry(&b2, &b3, &mut log)?;
        }
        if exists(&b1) {
            move_entry(&b1, &b2, &mut log)?;
        }
        move_entry(&tmp, &b1, &mut log)?;
        if had3 {
            fs::remove_file(&stage)?;
        }
        Ok(())
    })();

    if let Err(e) = outcome {
        rollback(&log, &tmp);
        fail(&format!("rotation failed: {}", e));
    }

    println!("rotated");
}

package main

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type fileInfo struct {
	rel  string // path relative to the root, slash-separated
	full string // real path used for reading
	size int64
}

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	os.Exit(1)
}

func inside(root, p string) bool {
	rel, err := filepath.Rel(root, p)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

func hashFile(p string) (string, error) {
	f, err := os.Open(p)
	if err != nil {
		return "", err
	}
	defer f.Close()
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return string(h.Sum(nil)), nil
}

func sameContent(a, b string) (bool, error) {
	fa, err := os.Open(a)
	if err != nil {
		return false, err
	}
	defer fa.Close()
	fb, err := os.Open(b)
	if err != nil {
		return false, err
	}
	defer fb.Close()

	ba := make([]byte, 64*1024)
	bb := make([]byte, 64*1024)
	for {
		na, erra := io.ReadFull(fa, ba)
		nb, errb := io.ReadFull(fb, bb)
		if erra != nil && erra != io.EOF && erra != io.ErrUnexpectedEOF {
			return false, erra
		}
		if errb != nil && errb != io.EOF && errb != io.ErrUnexpectedEOF {
			return false, errb
		}
		if na != nb || !bytes.Equal(ba[:na], bb[:nb]) {
			return false, nil
		}
		if erra != nil {
			// Both files ended at the same point with identical final chunks.
			return true, nil
		}
	}
}

func partition(list []fileInfo) ([][]fileInfo, error) {
	var classes [][]fileInfo
	for _, f := range list {
		placed := false
		for i := range classes {
			eq, err := sameContent(classes[i][0].full, f.full)
			if err != nil {
				return nil, err
			}
			if eq {
				classes[i] = append(classes[i], f)
				placed = true
				break
			}
		}
		if !placed {
			classes = append(classes, []fileInfo{f})
		}
	}
	return classes, nil
}

func main() {
	if len(os.Args) != 2 {
		fail("usage: PROGRAM DIR")
	}
	dirArg := os.Args[1]
	if dirArg == "" {
		fail("DIR must not be empty")
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine the current working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot resolve the current working directory")
	}

	absDir, err := filepath.Abs(dirArg)
	if err != nil {
		fail("cannot resolve DIR")
	}
	dirReal, err := filepath.EvalSymlinks(absDir)
	if err != nil {
		fail("DIR is not an existing folder")
	}
	info, err := os.Stat(dirReal)
	if err != nil || !info.IsDir() {
		fail("DIR is not an existing folder")
	}
	if !inside(cwdReal, dirReal) {
		fail("DIR is outside the current working directory")
	}

	// Collect regular files, never following symbolic links.
	var files []fileInfo
	err = filepath.WalkDir(dirReal, func(p string, d fs.DirEntry, werr error) error {
		if werr != nil {
			return werr
		}
		if !d.Type().IsRegular() {
			return nil
		}
		fi, ierr := d.Info()
		if ierr != nil {
			return ierr
		}
		rel, rerr := filepath.Rel(dirReal, p)
		if rerr != nil {
			return rerr
		}
		files = append(files, fileInfo{
			rel:  filepath.ToSlash(rel),
			full: p,
			size: fi.Size(),
		})
		return nil
	})
	if err != nil {
		fail("cannot read the directory tree")
	}

	// Group by size, then by hash, then verify by byte comparison.
	bySize := make(map[int64][]fileInfo)
	for _, f := range files {
		bySize[f.size] = append(bySize[f.size], f)
	}

	var groups [][]string
	for _, list := range bySize {
		if len(list) < 2 {
			continue
		}
		byHash := make(map[string][]fileInfo)
		for _, f := range list {
			h, herr := hashFile(f.full)
			if herr != nil {
				fail("cannot read a file")
			}
			byHash[h] = append(byHash[h], f)
		}
		for _, same := range byHash {
			if len(same) < 2 {
				continue
			}
			classes, perr := partition(same)
			if perr != nil {
				fail("cannot read a file")
			}
			for _, c := range classes {
				if len(c) < 2 {
					continue
				}
				paths := make([]string, 0, len(c))
				for _, f := range c {
					paths = append(paths, f.rel)
				}
				sort.Strings(paths)
				groups = append(groups, paths)
			}
		}
	}

	lines := make([]string, 0, len(groups))
	for _, g := range groups {
		lines = append(lines, strings.Join(g, " "))
	}
	sort.Strings(lines)

	for _, line := range lines {
		fmt.Fprintln(os.Stdout, line)
	}
	os.Exit(0)
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

type pair struct {
	old string
	nw  string
}

var oneLine = strings.NewReplacer("\n", `\n`, "\r", `\r`)

func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", oneLine.Replace(msg))
	os.Exit(1)
}

// display shows a name on one line; names with line breaks are quoted.
func display(name string) string {
	if strings.ContainsAny(name, "\r\n") {
		return strconv.Quote(name)
	}
	return name
}

// within reports whether target is base itself or lies inside base.
func within(base, target string) bool {
	rel, err := filepath.Rel(base, target)
	if err != nil || filepath.IsAbs(rel) {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

// rollback undoes the first n renames, in reverse order (best effort).
func rollback(dir string, renames []pair, n int) {
	for j := n - 1; j >= 0; j-- {
		_ = os.Rename(filepath.Join(dir, renames[j].nw), filepath.Join(dir, renames[j].old))
	}
}

func main() {
	args := os.Args[1:]
	if len(args) < 1 || len(args) > 2 {
		fail("usage: PROGRAM DIR [--apply]")
	}
	apply := false
	if len(args) == 2 {
		if args[1] != "--apply" {
			fail("second argument must be --apply")
		}
		apply = true
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwdReal, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot resolve working directory")
	}

	absDir, err := filepath.Abs(args[0])
	if err != nil {
		fail("invalid directory argument")
	}
	dirReal, err := filepath.EvalSymlinks(absDir)
	if err != nil {
		fail("not an existing folder: " + display(args[0]))
	}
	info, err := os.Stat(dirReal)
	if err != nil || !info.IsDir() {
		fail("not an existing folder: " + display(args[0]))
	}
	if !within(cwdReal, dirReal) {
		fail("directory is outside the working directory: " + display(args[0]))
	}

	entries, err := os.ReadDir(dirReal)
	if err != nil {
		fail("cannot read directory: " + display(args[0]))
	}

	taken := make(map[string]bool, len(entries))
	var candidates []string
	for _, e := range entries {
		name := e.Name()
		taken[name] = true
		if e.Type().IsRegular() && strings.Contains(name, " ") {
			candidates = append(candidates, name)
		}
	}
	sort.Strings(candidates)

	var lines []string
	var renames []pair
	for _, old := range candidates {
		nw := strings.ReplaceAll(old, " ", "_")
		if taken[nw] {
			lines = append(lines, "conflict: "+display(old))
			continue
		}
		lines = append(lines, display(old)+" -> "+display(nw))
		// Track the state as it is at this moment, so later
		// candidates see the effect of earlier renames.
		delete(taken, old)
		taken[nw] = true
		renames = append(renames, pair{old: old, nw: nw})
	}

	if apply {
		for i, p := range renames {
			src := filepath.Join(dirReal, p.old)
			dst := filepath.Join(dirReal, p.nw)
			if _, err := os.Lstat(dst); err == nil || !os.IsNotExist(err) {
				rollback(dirReal, renames, i)
				fail("target already exists or cannot be checked: " + display(p.nw))
			}
			if err := os.Rename(src, dst); err != nil {
				rollback(dirReal, renames, i)
				fail("cannot rename " + display(p.old) + " to " + display(p.nw))
			}
		}
	}

	w := bufio.NewWriter(os.Stdout)
	for _, line := range lines {
		w.WriteString(line + "\n")
	}
	_ = w.Flush()
	os.Exit(0)
}

package main

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const maxLinks = 40

type status int

const (
	inside status = iota
	outside
	missing
)

func main() {
	out, err := run(os.Args[1:])
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	if _, err := os.Stdout.Write(out); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	os.Exit(0)
}

func run(args []string) ([]byte, error) {
	if len(args) != 1 {
		return nil, errors.New("usage: PROGRAM LIST")
	}

	root, err := cwdReal()
	if err != nil {
		return nil, fmt.Errorf("cannot determine working directory: %v", err)
	}

	listArg := args[0]
	listPath, st := resolve(root, listArg)
	switch st {
	case outside:
		return nil, fmt.Errorf("list path is outside the working directory: %q", listArg)
	case missing:
		return nil, fmt.Errorf("cannot read list file: %q", listArg)
	}

	data, err := os.ReadFile(listPath)
	if err != nil {
		return nil, fmt.Errorf("cannot read list file: %q: %v", listArg, err)
	}

	var out bytes.Buffer
	for _, line := range strings.Split(string(data), "\n") {
		name := strings.TrimSuffix(line, "\r")
		if name == "" {
			continue
		}

		if filepath.IsAbs(name) {
			fmt.Fprintf(&out, "skipped: %s\n", name)
			continue
		}

		real, st := resolve(root, name)
		switch st {
		case outside:
			fmt.Fprintf(&out, "skipped: %s\n", name)
			continue
		case missing:
			fmt.Fprintf(&out, "missing: %s\n", name)
			continue
		}

		fi, err := os.Stat(real)
		if err != nil || !fi.Mode().IsRegular() {
			fmt.Fprintf(&out, "missing: %s\n", name)
			continue
		}

		content, err := os.ReadFile(real)
		if err != nil {
			return nil, fmt.Errorf("cannot read %q: %v", name, err)
		}

		fmt.Fprintf(&out, "== %s ==\n", name)
		out.Write(content)
		if len(content) > 0 && content[len(content)-1] != '\n' {
			out.WriteByte('\n')
		}
	}

	return out.Bytes(), nil
}

func cwdReal() (string, error) {
	wd, err := os.Getwd()
	if err != nil {
		return "", err
	}
	return filepath.EvalSymlinks(wd)
}

// within reports whether p (an absolute path, not cleaned, so that
// symlink-dependent ".." components are preserved) lies inside root.
// It returns the remainder of p relative to root.
func within(root, p string) (string, bool) {
	if p == root {
		return "", true
	}
	prefix := root
	if !strings.HasSuffix(prefix, string(filepath.Separator)) {
		prefix += string(filepath.Separator)
	}
	if strings.HasPrefix(p, prefix) {
		return p[len(prefix):], true
	}
	return "", false
}

func splitPath(p string) []string {
	return strings.Split(p, "/")
}

// resolve walks name starting from root (a real absolute directory),
// following symbolic links component by component. Any component that
// would take the walk outside root marks the path as outside; nothing
// outside root is ever touched.
func resolve(root, name string) (string, status) {
	cur := root
	var pending []string

	if filepath.IsAbs(name) {
		rest, ok := within(root, name)
		if !ok {
			return "", outside
		}
		pending = splitPath(rest)
	} else {
		pending = splitPath(name)
	}

	links := 0
	for len(pending) > 0 {
		comp := pending[0]
		pending = pending[1:]

		switch comp {
		case "", ".":
			continue
		case "..":
			if cur == root {
				return "", outside
			}
			cur = filepath.Dir(cur)
			continue
		}

		next := filepath.Join(cur, comp)
		fi, err := os.Lstat(next)
		if err != nil {
			return "", missing
		}
		if fi.Mode()&os.ModeSymlink == 0 {
			cur = next
			continue
		}

		links++
		if links > maxLinks {
			return "", missing
		}
		target, err := os.Readlink(next)
		if err != nil {
			return "", missing
		}
		if filepath.IsAbs(target) {
			rest, ok := within(root, target)
			if !ok {
				return "", outside
			}
			cur = root
			pending = append(splitPath(rest), pending...)
		} else {
			pending = append(splitPath(target), pending...)
		}
	}

	return cur, inside
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

var errOutside = fmt.Errorf("outside working directory")

func fail(msg string) {
	fmt.Fprintf(os.Stderr, "error: %s\n", msg)
	os.Exit(1)
}

// insideDir reports whether path lies within dir. Both must already be
// absolute and symlink-resolved.
func insideDir(dir, path string) bool {
	rel, err := filepath.Rel(dir, path)
	if err != nil {
		return false
	}
	if filepath.IsAbs(rel) {
		return false
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return false
	}
	return true
}

// countLines counts lines in r. A final line without a trailing newline
// still counts; an empty input has zero lines.
func countLines(r io.Reader) (int, error) {
	buf := make([]byte, 64*1024)
	newlines := 0
	total := 0
	var last byte
	for {
		m, err := r.Read(buf)
		if m > 0 {
			for _, b := range buf[:m] {
				if b == '\n' {
					newlines++
				}
			}
			last = buf[m-1]
			total += m
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return 0, err
		}
	}
	if total > 0 && last != '\n' {
		newlines++
	}
	return newlines, nil
}

// countWords counts whitespace-separated words in r.
func countWords(r io.Reader) (int, error) {
	br := bufio.NewReaderSize(r, 64*1024)
	n := 0
	inWord := false
	for {
		c, _, err := br.ReadRune()
		if err == io.EOF {
			break
		}
		if err != nil {
			return 0, err
		}
		if unicode.IsSpace(c) {
			inWord = false
		} else if !inWord {
			inWord = true
			n++
		}
	}
	return n, nil
}

// countFile returns the count of arg (using count) if it is a readable
// regular file inside cwd (already symlink-resolved). Nothing outside cwd
// is read.
func countFile(arg, cwd string, count func(io.Reader) (int, error)) (int, error) {
	abs, err := filepath.Abs(arg)
	if err != nil {
		return 0, err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return 0, err
	}
	if !insideDir(cwd, resolved) {
		return 0, errOutside
	}
	f, err := os.Open(resolved)
	if err != nil {
		return 0, err
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return 0, err
	}
	if !fi.Mode().IsRegular() {
		return 0, fmt.Errorf("not a regular file")
	}
	return count(f)
}

func main() {
	args := os.Args[1:]

	count := countLines
	if len(args) > 0 && args[0] == "--words" {
		count = countWords
		args = args[1:]
	}

	if len(args) == 0 {
		fail("no files given")
	}

	wd, err := os.Getwd()
	if err != nil {
		fail("cannot determine working directory")
	}
	cwd, err := filepath.EvalSymlinks(wd)
	if err != nil {
		fail("cannot resolve working directory")
	}

	allOK := true
	sum := 0
	for _, a := range args {
		n, err := countFile(a, cwd, count)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", a)
			allOK = false
			continue
		}
		fmt.Printf("%d %s\n", n, a)
		sum += n
	}
	fmt.Printf("total %d\n", sum)

	if !allOK {
		os.Exit(1)
	}
	os.Exit(0)
}

package main

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	kept, dropped, err := run(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error: "+err.Error())
		os.Exit(1)
	}
	fmt.Printf("kept %d dropped %d\n", kept, dropped)
}

func run(args []string) (int, int, error) {
	if len(args) != 2 {
		return 0, 0, errors.New("usage: PROGRAM IN OUT")
	}

	cwd, err := os.Getwd()
	if err != nil {
		return 0, 0, errors.New("cannot determine working directory")
	}
	cwd, err = filepath.EvalSymlinks(cwd)
	if err != nil {
		return 0, 0, errors.New("cannot determine working directory")
	}

	inPath, err := resolveIn(cwd, args[0])
	if err != nil {
		return 0, 0, err
	}
	data, err := os.ReadFile(inPath)
	if err != nil {
		return 0, 0, fmt.Errorf("cannot read IN: %s", args[0])
	}

	outPath, exists, err := resolveOut(cwd, args[1])
	if err != nil {
		return 0, 0, err
	}

	var mode fs.FileMode
	if exists {
		info, serr := os.Stat(outPath)
		if serr != nil || !info.Mode().IsRegular() {
			return 0, 0, fmt.Errorf("cannot write OUT: %s", args[1])
		}
		mode = info.Mode().Perm()
		f, oerr := os.OpenFile(outPath, os.O_WRONLY, 0)
		if oerr != nil {
			return 0, 0, fmt.Errorf("cannot write OUT: %s", args[1])
		}
		f.Close()
	}

	seen := make(map[string]struct{})
	var out strings.Builder
	kept, total := 0, 0
	text := string(data)
	if text != "" {
		lines := strings.Split(text, "\n")
		if strings.HasSuffix(text, "\n") {
			lines = lines[:len(lines)-1]
		}
		total = len(lines)
		for _, line := range lines {
			if _, ok := seen[line]; ok {
				continue
			}
			seen[line] = struct{}{}
			out.WriteString(line)
			out.WriteByte('\n')
			kept++
		}
	}
	dropped := total - kept

	if werr := writeFile(outPath, out.String(), exists, mode); werr != nil {
		return 0, 0, fmt.Errorf("cannot write OUT: %s", args[1])
	}
	return kept, dropped, nil
}

func absJoin(cwd, raw string) string {
	if filepath.IsAbs(raw) {
		return raw
	}
	return cwd + string(filepath.Separator) + raw
}

func inside(cwd, p string) bool {
	rel, err := filepath.Rel(cwd, p)
	if err != nil {
		return false
	}
	return rel != ".." &&
		!strings.HasPrefix(rel, ".."+string(filepath.Separator)) &&
		!filepath.IsAbs(rel)
}

func resolveIn(cwd, raw string) (string, error) {
	real, err := filepath.EvalSymlinks(absJoin(cwd, raw))
	if err != nil {
		return "", fmt.Errorf("cannot read IN: %s", raw)
	}
	if !inside(cwd, real) {
		return "", fmt.Errorf("path outside working directory: %s", raw)
	}
	return real, nil
}

// resolveOut returns the fully resolved target path for OUT, whether it
// currently exists, or an error. Nothing is created or modified here.
func resolveOut(cwd, raw string) (string, bool, error) {
	full := absJoin(cwd, raw)
	real, err := filepath.EvalSymlinks(full)
	if err == nil {
		if !inside(cwd, real) {
			return "", false, fmt.Errorf("path outside working directory: %s", raw)
		}
		return real, true, nil
	}
	if !errors.Is(err, fs.ErrNotExist) {
		return "", false, fmt.Errorf("cannot write OUT: %s", raw)
	}
	// A dangling symlink exists as a link but cannot be resolved safely.
	if _, lerr := os.Lstat(full); lerr == nil {
		return "", false, fmt.Errorf("cannot write OUT: %s", raw)
	}
	dirPart, base := filepath.Split(full)
	if base == "" || base == "." || base == ".." {
		return "", false, fmt.Errorf("cannot write OUT: %s", raw)
	}
	realDir, err := filepath.EvalSymlinks(dirPart)
	if err != nil {
		return "", false, fmt.Errorf("cannot write OUT: %s", raw)
	}
	if !inside(cwd, realDir) {
		return "", false, fmt.Errorf("path outside working directory: %s", raw)
	}
	target := filepath.Join(realDir, base)
	if !inside(cwd, target) {
		return "", false, fmt.Errorf("path outside working directory: %s", raw)
	}
	return target, false, nil
}

// writeFile writes content to a temporary file in the same directory and
// renames it over path, so a failure leaves the original file untouched.
func writeFile(path, content string, exists bool, mode fs.FileMode) error {
	dir := filepath.Dir(path)
	tmp, err := os.CreateTemp(dir, ".dedup-*.tmp")
	if err != nil {
		return err
	}
	name := tmp.Name()
	ok := false
	defer func() {
		if !ok {
			tmp.Close()
			os.Remove(name)
		}
	}()

	if _, err := tmp.WriteString(content); err != nil {
		return err
	}
	if err := tmp.Sync(); err != nil {
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if exists {
		if err := os.Chmod(name, mode); err != nil {
			return err
		}
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	ok = true
	return nil
}

package main

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

type rename struct{ from, to string }

func fail(msg string) {
	fmt.Fprintln(os.Stderr, "error: "+msg)
	os.Exit(1)
}

// inside reports whether p lies within root (both absolute, symlinks already resolved).
func inside(root, p string) bool {
	rel, err := filepath.Rel(root, p)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel)
}

// backupExists reports whether a backup path exists. It fails if the path is
// not a regular file, or a symbolic link resolving outside root.
func backupExists(path, root string) bool {
	fi, err := os.Lstat(path)
	if os.IsNotExist(err) {
		return false
	}
	if err != nil {
		fail("cannot inspect " + path)
	}
	if fi.Mode()&os.ModeSymlink != 0 {
		target, err := filepath.EvalSymlinks(path)
		if err != nil || !inside(root, target) {
			fail(path + " resolves outside the current directory")
		}
		return true
	}
	if !fi.Mode().IsRegular() {
		fail(path + " is not a regular file")
	}
	return true
}

// copyToTemp copies src to a new temporary file in dir and returns its name.
func copyToTemp(src, dir, base string, perm os.FileMode) (string, error) {
	in, err := os.Open(src)
	if err != nil {
		return "", err
	}
	defer in.Close()

	out, err := os.CreateTemp(dir, "."+base+".copy-*")
	if err != nil {
		return "", err
	}
	name := out.Name()
	_, err = io.Copy(out, in)
	if err == nil {
		err = out.Chmod(perm)
	}
	if err == nil {
		err = out.Sync()
	}
	if cerr := out.Close(); err == nil {
		err = cerr
	}
	if err != nil {
		_ = os.Remove(name)
		return "", err
	}
	return name, nil
}

func main() {
	if len(os.Args) != 2 {
		fail("usage: PROGRAM FILE")
	}

	cwd, err := os.Getwd()
	if err != nil {
		fail("cannot determine current directory")
	}
	root, err := filepath.EvalSymlinks(cwd)
	if err != nil {
		fail("cannot resolve current directory")
	}

	// Split the raw argument before cleaning so symlinks are resolved
	// in the correct order when the directory part is resolved.
	raw := os.Args[1]
	if !filepath.IsAbs(raw) {
		raw = root + string(filepath.Separator) + raw
	}
	idx := strings.LastIndexByte(raw, filepath.Separator)
	dirPart := raw[:idx]
	if dirPart == "" {
		dirPart = string(filepath.Separator)
	}
	base := raw[idx+1:]
	if base == "" || base == "." || base == ".." {
		fail("FILE must name a file")
	}

	dir, err := filepath.EvalSymlinks(dirPart)
	if err != nil {
		fail("cannot resolve directory of FILE")
	}
	if !inside(root, dir) {
		fail("FILE is outside the current directory")
	}

	file := filepath.Join(dir, base)
	fi, err := os.Lstat(file)
	if err != nil || !fi.Mode().IsRegular() {
		fail("FILE is not an existing regular file")
	}

	b1 := filepath.Join(dir, base+".1")
	b2 := filepath.Join(dir, base+".2")
	b3 := filepath.Join(dir, base+".3")
	has1 := backupExists(b1, root)
	has2 := backupExists(b2, root)
	has3 := backupExists(b3, root)

	// Make the copy first so that nothing is changed if it fails.
	tmp, err := copyToTemp(file, dir, base, fi.Mode().Perm())
	if err != nil {
		fail("cannot copy FILE: " + err.Error())
	}

	var done []rename
	trash := ""

	rollback := func() {
		for i := len(done) - 1; i >= 0; i-- {
			_ = os.Rename(done[i].to, done[i].from)
		}
		_ = os.Remove(tmp)
	}
	abort := func(msg string) {
		rollback()
		fail(msg)
	}
	move := func(from, to string) error {
		if err := os.Rename(from, to); err != nil {
			return err
		}
		done = append(done, rename{from, to})
		return nil
	}

	// Delete FILE.3 by renaming it to a reserved name, removed at the end.
	if has3 {
		f, err := os.CreateTemp(dir, "."+base+".trash-*")
		if err != nil {
			abort("cannot prepare rotation")
		}
		trash = f.Name()
		if err := f.Close(); err != nil {
			_ = os.Remove(trash)
			abort("cannot prepare rotation")
		}
		if err := move(b3, trash); err != nil {
			_ = os.Remove(trash)
			abort("cannot rotate " + b3)
		}
	}
	if has2 {
		if err := move(b2, b3); err != nil {
			abort("cannot rotate " + b2)
		}
	}
	if has1 {
		if err := move(b1, b2); err != nil {
			abort("cannot rotate " + b1)
		}
	}
	if err := move(tmp, b1); err != nil {
		abort("cannot create " + b1)
	}
	if trash != "" {
		if err := os.Remove(trash); err != nil {
			abort("cannot remove old " + b3)
		}
	}

	fmt.Println("rotated")
}
